// ============================================================
// 灰盒原型数值配置
// 状态：全部为灰盒估计值，需实测修订。调参只改这个文件。
// 对应文档：docs/01-产品设计文档.md、docs/02-技术实现方案.md
// ============================================================

export const VIEW = { w: 1280, h: 720 };

/**
 * 摄像机（2026-09-29 新增**纵向跟随**）。
 *
 * 背景：原来相机只有横向（`camera.x`），纵向是 1:1 直通的 —— 而**屏幕上方的 HUD 固定在屏幕坐标里**，
 *   于是"人物上到岩桥"（世界 y ≈ 250）时，人物正好落在**横幅**（屏幕 320~960 × 210~294）
 *   那一片 → 提示语直接把人物盖住（用户："一些提示语会挡画面"）。
 *
 * 做法：**人物越靠上，画面整体越往下推**（= 视角跟着上移），让人物的脚底永远不高过 `safeTop`。
 *   屏幕 y = 世界 y + `camera.y`（见 render.js 的 `translate`、main.js 的 `toWorld`）。
 *
 * ⚠️ `safeTop = 350` 是**量出来的**，不是拍的 —— 三条依据：
 *   ① 屏幕上会跟人物抢中线的只有两块：**横幅**（320~960 × 210~294）和
 *      **庇护所属性面板**（466~986 × 16~302，底边 302）。人物恒在屏幕中线 x = 640，
 *      而 HUD 块（16~446）、小地图（16~396）、仓库（1000~1264）都碰不到中线。
 *   ② 人物画到 `p.y - 34`（头顶），头顶那行状态字再往上 24 → 要留 ~60px 的空。
 *      → 350 时头顶在 316，刚好落在 302 / 294 之下。
 *   ③ 取 350 之后，**站最高那条桥（y ≈ 250）时地面仍在屏幕里**（570 + 100 = 670 < 720）。
 *
 * ⚠️ 只在人物**高于** `safeTop` 时才推：地面高度（570）和跳跃顶点（实测 62.35 → y ≈ 508）
 *   都够不到它 → **平地走路和跳一下的观感完全不变**。这是它做成"跟随"而不是"重设机位"的原因。
 * ⚠️ 地下同样生效：那里地形也能抬到 y ≈ 310（`TERRAIN.maxRise`），最多推 40px，无害。
 * ⚠️ 改这个值要重看三处：最高桥上的地面还在不在画面里、头顶会不会露出面板、平地是否仍然零位移。
 */
export const CAMERA = {
  // ⚠️ **屏幕坐标下的 y 线**（不是世界 y）：人物的屏幕高度低于它，就把画面往下推。
  //    拉近之后 `main.js` 会把它反解成世界口径（见那里的注释）—— 改 zoom 时不用动这个数。
  safeTop: 350,
  // ---------- 镜头拉近（2026-10-05，用户："人物看上去有点小，能不能把镜头拉近一点，
  //            视野范围小一点，这样显得人物大一些"）----------
  // 世界整体放大这么多倍再画 ⇒ **可视世界宽度 = `VIEW.w / zoom`**（1280 / 1.5 ≈ **853**），
  // 人物（34px 高）在屏幕上就变成约 **51px**。
  // ⚠️⚠️ **只放"世界"那一层**：UI（HUD / 面板 / 小地图 / 横幅）必须保持 1:1 ——
  //    它们的坐标是按 1280×720 写死的，跟着一起缩放会**直接跑出画布**。
  // ⚠️ 它一动，这三处必须跟着动（都是一次性的逆运算，漏一处就"点击落点整体偏移"且不报错）：
  //    ① `main.js` 的 `updateCamera()` —— 可视半宽变成 `VIEW.w / zoom / 2`，纵向跟随也要换算
  //    ② `render.js` 画世界前那三行 canvas 变换（`translate(锚点) → scale(zoom) → translate(-相机)`)
  //    ③ `render.js` 的 `drawDarkness()` 与地下的洞顶那段 —— 它们画在**屏幕坐标**下，要乘 zoom
  //    而 ② 的逆运算就是下面的 `screenToWorld()` —— **两边必须逐字对应**，所以抽出来了。
  // ⚠️⚠️ **优先选"整比"**（2026-10-05 用户"再大一些"时补的）：世界是像素画，缩放比越"整"，
  //    每个源像素在屏幕上占的格数越均匀 —— **1.25（4:5）· 1.5（2:3）· 2.0（1:2）都不会出现
  //    "1px/2px 混着"**，而 **1.35 / 1.75 这种非整比会让一部分像素宽一档**（缩到手机上不明显，
  //    但能避免就避免）。⇒ 想再大，下一档直接上 **2.0**（可视宽度只剩 640，已经很近）。
  zoom: 1.5,
};

export const WORLD = {
  // ⚠️ 2026-09-27 第四轮：2600 → **4800**（用户要求"扩大地图面积"）。庇护所保持居中。
  // ⚠️⚠️ 这一轮把"各区区间"从**硬编码绝对坐标**改成**按相对距离推导**（见 `zoneEdges` +
  //    `zoneRanges()`）。前两轮每次改宽度都要手算一堆坐标，而且漏改过 ——
  //    "世界加宽后绝对坐标没跟着平移"是 docs/04 里记过的一族病。现在改宽度只动两个数字。
  // ⚠️ "扩大面积"**不等于"把东西摊得更开"**：各区点数会按面积同步增加（见 ZONES.perSide），
  //    否则靠近庇护所的地方就没料可挖 → 每趟都被迫跑远 → 180 秒准备期直接崩。
  width: 4800,
  groundY: 570,
  // 各区相对庇护所的**边界距离**（从内到外，单位 px）：
  //   近区 340~700 / 中区 700~1050 / 深区 1050~1600 / 极深区 1600~2200
  //   ⚠️ 数组长度 = 区数 + 1；加区/改宽度都只改这里。
  zoneEdges: [340, 700, 1050, 1600, 2200],
};

// ============================================================
// 世界 ↔ 屏幕（2026-10-05 随"镜头拉近"抽出：**唯一入口**）
// ============================================================
/**
 * 拉近时的**纵向缩放锚点**：以"地面线"为中心缩放。
 *
 * ⚠️ 为什么锚在地面、而不是画布中心：锚在画布中心（y=360）会把人物整体往下压 ——
 *    实测地面会从屏幕 570 掉到 **643**，而底部那块面板带（背包面板 590~676）正好在那儿
 *    → **人被面板盖住** ✗。锚在地面线 ⇒ **地面与人物站位一个像素不动**，
 *    只有"地面之上 / 之下"的东西被放大 ✓（顺带：底部那条地下岩层的可见高度也不变）。
 */
export const CAMERA_ANCHOR_Y = WORLD.groundY;

/**
 * 屏幕坐标 → 世界坐标。**世界↔屏幕换算的唯一入口**（`main.js` 的点击判定全走它）。
 *
 * ⚠️⚠️ 它必须是 `render.js` 画世界前那几行的**逆运算**：
 *     `translate(shx, shy) → translate(0, ANCHOR_Y*(1-zoom)) → scale(zoom) → translate(-camera.x, +camera.y)`
 *     ⇒ 屏幕 = `(世界 − camera) × zoom`，其中 y 再以 `ANCHOR_Y` 为锚：
 *        `screen_y = (world_y + camera.y − ANCHOR_Y) × zoom + ANCHOR_Y`
 *     逆过来就是下面两行。**改一边必须改另一边** —— 漂了的表现是"看着在哪、点在哪"错开，
 *     而且**一行都不报错**（本项目在"漏 import"和"漏偏移"上各栽过一次）。
 */
export function screenToWorld(sx, sy, camera) {
  const z = CAMERA.zoom;
  return {
    x: sx / z + camera.x,
    y: (sy - CAMERA_ANCHOR_Y) / z - camera.y + CAMERA_ANCHOR_Y,
  };
}

// ============================================================
// 调色板（2026-10-01 新增：荒诞几何风格 → "贫民铁锈"调子）
// ============================================================
// 为什么单独抽出来：本轮之前颜色是**硬编码散在 render.js 上百处**的，改一个调子要全局
//   搜替换、还容易漏；而且 `tools/hue-audit.js` 得**读得到**"环境暗阶到底有多暗"，
//   才能守住"环境和材料不撞色"这条线。凡是被判定要守的色，必须从这里出。
//
// ⚠️ 本轮只收**环境色 + 黑幕/光圈色** —— HUD 皮肤、动效/粒子、材料色都不在本轮范围：
//    材料色仍归 `MATERIALS`（本文件），HUD 仍是 render.js 里的硬编码。
//
// ⚠️⚠️ 环境色为什么必须这么暗：B 贫民铁锈的暖色相（13°~38°）正压在**材料最密的
//    0°~59° 带**上 —— 色相已经分不开"环境"和"材料"了，只能改由**明度**分层。
//    实测（`node prototype/tools/hue-audit.js`）：全部带色材料里最暗的是 `t7_hard_tough`
//    `#5f4b3c`（L=30.4%），**L < 30% 的材料一件都没有**。
//    → 所以 `ENV_SURFACES` 这四个大面积色的 L 必须 **≤ 28%**（留 2 个点余量）。
//      这条由 hue-audit.js 断言，破了下一次跑审计就红。
//    ⚠️ 反过来：`#8C5A3C`（L=39%）这种"中档铁锈"**不能拿来当环境色**（比最暗的材料还亮，
//       材料和地形会糊在一起），它只能进 HUD —— HUD 画在 drawDarkness **之后**，
//       永远不被压暗，是唯一安全的高亮舞台。
//
// 换算：L = (max(R,G,B) + min(R,G,B)) / 2 / 255，即 HSL 的 L（不是感知亮度）。
export const PALETTE = {
  // ---- 环境（大面积；L ≤ 28%，由 hue-audit.js 守）----
  envDeep: '#241A16',    // L=11.4% h=13° 最暗：天空底色 / 洞顶岩带
  envMid:  '#2B1F17',    // L=12.9% h=21° 中间层：洞顶钟乳石
  envFill: '#4A3428',    // L=22.4% h=19° 地形主体
  envEdge: '#5F4329',    // L=26.7% h=24° 地形顶面描边（"地平线"）
  // ---- 黑幕 / 光圈（本轮氛围层的核心）----
  // ⚠️ 这两个是**逗号分隔的 RGB 字符串**、不是 hex：drawDarkness 要按透明度现拼
  //    `rgba(...)`，写成 hex 每处还得再转一遍。
  darkRgb: '20,11,5',    // 暖黑（h≈24°）：原来是中性偏蓝的 `4,6,10`
  glowRgb: '255,176,96', // 光锥中心的暖光（h≈31°）：开灯才叠，关灯几乎不叠
};

// 必须整体低于"最暗材料"（L=30.4%）的那几个大面积环境色 —— hue-audit.js 按这份清单
// 逐一断言。⚠️ 往这里加色之前先跑一次 `node prototype/tools/hue-audit.js`，L 超了会直接红。
export const ENV_SURFACES = ['envDeep', 'envMid', 'envFill', 'envEdge'];

// ============================================================
// HUD 皮肤（2026-10-01：环境调子落地后，UI 跟着统一）
// ============================================================
// 为什么单独抽出来：上一轮把"环境色"收进 `PALETTE` 时留了一句话 ——「凡是被判定要守的色，
//    必须从这里出」。而 HUD 是**要守的色最多**的地方：本轮之前 render.js 里有 14 处
//    硬编码面板底（全是 `rgba(10,14,20,α)` 一家）+ 8 种散落的强调色。
//
// ⚠️⚠️ HUD 底色**不能提亮**。这是"贫民铁锈"这个暖色相换来代价的直接兑现：
//    暖色相（13°~38°）压住了材料最密的 0°~59° 带 → 色相分不开，只能靠**明度**分层。
//    而背包 / 仓库的格子里**直接叠着材料图标**，最暗的材料 `t7_hard #3d4557` 只有 L=29%
//    （实测，见 `tools/hue-audit.js`）→ 面板底一旦超过约 20%，材料就和底糊在一起。
//    → 所以本轮的"铁锈感"**全部下在边、铆钉、文字上**，底色只做一件事：冷黑换成暖黑。
//    这条由 `hue-audit.js` 断言（面板底 < 最暗材料），破了下一次跑审计就红。
//
// ⚠️ 底色刻意**复用黑幕的暖黑**（= `PALETTE.darkRgb` 的 `20,11,5`，h≈24°）而不是另配一个 ——
//    HUD 和黑幕、地形因此是同一个色系，不会出现"HUD 是暖的、世界是冷的"这种断层。
//
// 换算：L = (max(R,G,B) + min(R,G,B)) / 2 / 255，即 HSL 的 L（不是感知亮度）。
export const UI_SKIN = {
  // ---- 面板底 / 边（"轻质感"三件套：切角、铁锈边、四角铆钉）----
  panelRgb: '20,11,5',   // 暖黑（= PALETTE.darkRgb）—— 见上面那条"不能提亮"
  panelA: 0.86,          // 常驻面板（状态面板 / 背包 / 仓库 / 小地图）
  panelAStrong: 0.94,    // 必须挡住世界的（合成面板 / 材料提示框 / 横幅）
  panelASoft: 0.55,      // 示意性质的小块（脚下的"暂存堆"标签）
  rivet: '#879384',      // 回收金属边缘；不改变世界与材料的固有色。
  rivetHi: '#C6BD94',    // 磨损金属与铆钉受光面。
  slotBg: 'rgba(255,255,255,0.06)',   // 有东西的格子
  slotBgEmpty: 'rgba(0,0,0,0.30)',    // 空格子
  slotEdge: 'rgba(135,147,132,0.65)', // 材料格边缘，弱于选中状态。

  // ---- 文字三级灰阶（暖）----
  // ⚠️ 冷白（#e8eef6）压在暖黑底上会显得**发青**，像没调过色的旧 UI —— 所以整体偏暖。
  textStrong: '#F1ECDA',
  textMid: '#BEC6B6',
  textDim: '#929C8E',

  // ---- 5 个语义色（状态轴）----
  // 收敛前是 8 种，其中 3 个绿青（#4caf50 / #8fd694 / #6fc3a8 语义重复）、
  // 外加冷青蓝（#7ad3ff）和冷紫（#c7b9e8）在暖底上很跳。现在归成 5 个：
  ok: '#9DC46B',      // 成功 / 正常 / 完全免伤 / 血条健康
  warn: '#FFB300',    // 注意（比 danger 轻一档的提醒）
  danger: '#FF5A4A',  // 危险 / 扣血 / 破面 / 怪物贴脸
  info: '#6FBBA8',    // 信息 / 可交互 / 进度 —— **铜绿**：锈蚀世界里的"信息色"
  hi: '#FFD166',      // 高亮 / 选中 / 稀有

  // ---- 3 个类别色（另一条轴：结 / 功 / 修）----
  // ⚠️ 刻意**没有**并进上面那 5 个：它们是"这是哪个类别"，不是"现在什么状态"。
  //    并掉的话，背包 / 仓库里 结/功/修 就只能靠那一个字区分了。
  //    色值上和 ok / info 撞了是有意的（同一族色，视觉上成体系）。
  kindStruct: '#9DC46B',
  kindFunc: '#C9A0BE',    // 原冷紫 #c7b9e8 → 藕荷（暖）
  kindRepair: '#6FBBA8',
};

// 必须暗于"最暗材料"的那几个 HUD 大面积色（键名 → UI_SKIN 里的字段）—— hue-audit.js 断言。
export const UI_DARK_SURFACES = ['panelRgb'];

// 启动自检：`UI_DARK_SURFACES` 是一份**键名清单**（弱引用），和 `ENV_SURFACES` 同类。
// ⚠️ 键名打错在运行期是**静默**的：审计脚本 `UI_SKIN[key]` 拿到 undefined、只打一行 ✗ 就走了，
//    而运行时 `panelPlate` 照样画（它会拼出 `rgba(undefined,0.86)` → 底色悄悄变成默认黑/透明）。
//    "字符串弱引用必须配启动自检"是本项目记过好几遍的一条（掉落表 id / 材料表专长 / DISASTERS 键名）。
{
  const bad = [];
  for (const key of UI_DARK_SURFACES) {
    const raw = UI_SKIN[key];
    if (typeof raw !== 'string' || !/^\d{1,3},\d{1,3},\d{1,3}$/.test(raw.trim())) {
      bad.push(`${key} → ${JSON.stringify(raw)}（必须是形如 '20,11,5' 的 RGB 串）`);
    }
  }
  if (bad.length) throw new Error('UI_SKIN 的底色键名 / 格式写错了（HUD 底色会静默失效、审计也守不住）：\n  ' + bad.join('\n  '));
}

// ============================================================
// 世界物件固有色（2026-10-01：HUD 皮肤之后，把世界里的物件也拉回暖色系）
// ============================================================
// 为什么单独一组：这些东西**不是环境**（环境是天空 / 地形那种大面积底色，见 `PALETTE`），
//   也**不是 UI**（UI 是屏幕坐标的面板，见 `UI_SKIN`）—— 它们是"世界里的具体物件"：
//   悬空岩桥 / 天然石台 / 岩棚 / 碎石堆 / 升降台 / 地穴口 / 隧道口 / 工作台 / 墙体外框。
//
// ⚠️⚠️ 刻意**不包含**的（用户 2026-10-01 明确划出）：**玩法识别色** —— 主角的冷蓝
//    `#5bc0eb`、怪物的红、区域的四个色带与区域名（近/中/深/地下）、灾害地面 tint、
//    以及"地下"那一族冷紫 `#c7b9e8`。它们的颜色**本身在编码玩法信息**，
//    改了等于让玩家重新学一遍"谁是谁"（见 docs/04「色彩维度被玩法占用」那条）。
//    ⚠️ 连带效果：升降台/地穴口上那些"指向哪一层"的紫/金**保持原样** —— 它们和
//       区域色带说的是同一件事，只换物件本体、不换语义标注，否则会出现
//       "标注是冷紫、标签是暖藕荷"这种自相矛盾的搭配。
//
// ⚠️ 色相全部落在 **17°~38°**（暖灰铁锈）。这条由 `hue-audit.js` 断言：
//    往这里加色时，只要色相跑到带外（例如顺手塞一个冷蓝），审计直接红。
export const OBJ_SKIN = {
  // ---- 暖灰铁锈阶（暗 → 亮）----
  deep: '#241A16',   // L=11.4% h=17° 洞口深处 / 缝隙 / 墙体外框
  dark: '#2E251E',   // L=14.9% h=26° 空墙格 / 桥体暗面（分叉支桥）
  mid:  '#3A3129',   // L=19.4% h=28° 升降台柱体 / 工作台腿 / 打穿的墙格
  body: '#4A3F33',   // L=24.5% h=31° 岩板 / 石台 / 石堆 / 台面
  top:  '#5C5044',   // L=31.4% h=30° 石堆顶面 / 桥面（"这一条能站"的高光）
  lit:  '#6A5C4A',   // L=35.3% h=34° 受光面：料堆最上面那块石头（比 top 再亮一档）
  deck: '#B9A488',   // L=62.9% h=34° 升降台可站立的台面（必须够亮才一眼看出"能站"）
  // ---- 工作台的木质件（本来就偏暖，收进来只是为了让这一组是完整的"物件固有色总表"）----
  woodBar:  '#6B5B46',   // L=34.7% h=34° 台面上那条工具槽
  woodTool: '#8A7A5E',   // L=45.5% h=38° 台上的工具
};

// ============================================================
// 庇护所外壳固有色（**飞船** · 2026-10-03）
// ============================================================
// ⚠️⚠️ 这是**故意破例**的一组：`OBJ_SKIN` 的色相被 `hue-audit.js` 锁在 **17°~38°**（暖灰铁锈），
//    而这里全是 **165°~180° 的深青**。破例的理由（用户 2026-10-03 定）：
//      ① 庇护所是**玩家唯一拥有的东西**，让它一眼区别于世界上其他所有物件是**玩法收益**；
//      ② 用户要的是"科技感"，而科技感在这个画面里只能靠冷色表达（暖色已经全部是"环境 / 石木"的语言）。
//    ⚠️ 代价（不是没有，写在这里免得以后忘）：冷青落在**材料的色相范围（实测 0°~256.3°）**里，
//       所以墙板在理论上可能被看成一颗粒 —— 实际靠两条挡住：墙板是**大面积连续块**、
//       而材料永远是 11~18px 的小方块（尺寸差异 + 位置差异）。
//    ⚠️ `hue-audit.js` 里有一条**具名豁免**指着这个对象；往这里加色 **不会**被审计拦，
//       所以更要自己守着"别越出深青一族"。
export const SHELL_SKIN = {
  deep: '#0A1412',   // 缝隙 / 墙板垫底
  dark: '#0B1F1D',   // 最暗面
  mid:  '#14332F',   // 暗部
  body: '#1E4A47',   // 主体（占比最大的一档）
  lit:  '#2A625C',   // 受光面
  glow: '#6FBBA8',   // 棱线 / 能量线 —— **= UI_SKIN.info 的铜绿**（同一个值，刻意不引用，
                     //   理由同 IDENTITY.monsterEye：这一组要能自己读得通）
};

// 物件固有色必须落在暖色带里 —— 见上面那段"刻意不包含玩法识别色"。
export const OBJ_HUE_RANGE = [5, 60];

// ============================================================
// 身份色（2026-10-01）—— "哪个是我 / 哪个会咬我 / 我在哪个区"
// ============================================================
// 和上面三组的区别：`PALETTE` = 环境（天空 / 地形的底色）、`UI_SKIN` = HUD、`OBJ_SKIN` = 世界物件本体。
//   这一组是**玩法识别色** —— 颜色本身就是信息。它长期硬编码散在 render.js 里，
//   而且是画面里**最后的冷色来源**（主角冷蓝 / 近区冷蓝 / 地下冷紫）。
//
// ⚠️ 改这一组的原则：**只动色相，保留语义关系**（见 docs/04 那条"换色系要按相对关系挑档位"）。
//    具体要保住的三条：
//      ① 主角必须是**全屏最容易被找到的东西** → 它和材料的区分走**两条分支之一**：
//         要么**色相**远离全部材料，要么**近无彩且比所有材料都亮**（hue-audit.js 两边都有断言）；
//      ② 怪物本体要**暗于** danger 那个"警告红"，否则常驻怪物 + 常驻告警 = 满屏都在报警；
//      ③ 区域的四个色是**递进**的（越远越深越险），不是四个并列的分类色。
export const IDENTITY = {
  // ---- 主角 ------------------------------------------------
  // ⚠️ 2026-10-02 换成**近无彩的冷白**（原是自己挑的品红紫 `#E07AC8`）。理由：
  //    ① 实测材料占满了 **0°~256.3°** 这一段有彩度色相（见 `hue-audit.js`）——
  //       保持高彩度的话，合法区**只剩 282°~335° 那 54° 的紫系**，换色等于只能在紫里挪；
  //    ② 于是改用另一条轴：**"近无彩" + "全屏最亮"**。材料**全都是有彩度的**，
  //       而近无彩 + 比**所有**材料都亮这两条同时成立时，它就不可能被看成一颗粒。
  //    ⚠️ 上界（"必须最亮"）是**硬要求**，不是形容词：实测最亮的材料不是我以为的
  //       `t1_gloss`(L=83.9%)，而是功能件 `mir1 #cfe8ff` **L=90.6%** —— 第一版选的
  //       `#DFE0E2`(L=88%) 就是被这条打回的（比 mir1 还暗）。本值 L=95.7%。
  //    📊 2026-10-02：道具档位颜色重排（6 组 × 3 档拉开明度）之后 `mir1` 降到 80%，
  //       **最亮的材料又变回 `t1_gloss #c5dce7` L=83.9%** → 门槛变成 ≥85.9%，
  //       主角 95.7% 的余量从 3.1pp 扩到 **9.8pp**（更安全，但这条断言仍然守着）。
  //    ⚠️ 代价：审计里那条"色相 ≥ 25°"对无彩色是**空转**（它仍按色相比）。所以
  //       `hue-audit.js` 加了**无彩分支**：用**绝对彩度** `c = max−min` 判（不能用 HSL 的 `s`，
  //       后者在 l→1 时会炸），`c < 0.05` 时豁免色相、改判"明度高出最亮材料 ≥ 2%"。
  //       **动这个色值必须重跑 `node prototype/tools/hue-audit.js`。**
  player: '#F2F4F6',          // c=0.016 L=95.7%  近无彩冷白（全屏最亮）
  playerRing: '242,244,246',  // = player 的 rgb（要打透明度的变体统一从这一份现拼）
  playerDead: '#7A2A2A',      // 死了：暗下去（不是换色相，是"褪色"）
  playerHurt: UI_SKIN.danger, // 刚被咬：闪红
  playerStun: UI_SKIN.warn,   // 被塌方埋住：闪琥珀

  // ---- 怪物 -------------------------------------------------
  monster: '#B0342C',         // h=6° L=43%  砖红（刻意暗于 danger #FF5A4A 的 L=64%）
  // ⚠️ 原来这里还有个 `monsterRing`（"预警 / 咬住圈"的亮红）—— 2026-10-05 用户
  //    "不要那个红圈了"，画圈的代码整个删掉，这个色号也一并删（留着就是死条目）。
  monsterEye: '#FFD166',      // = UI_SKIN.hi 的值（不引用它，是为了这一组自己读得通）

  // ---- 区域（一条"越远越深"的暖色明暗梯度，不是四个并列分类色）----
  // ⚠️ 原来是"近=冷蓝 / 中=黄 / 深=橙 / 地下=冷紫" —— 那两个冷色就是这么来的。
  //    现在整条梯度都在暖色里走：浅土黄 → 土橙 → 锈红 → 暗紫棕。
  //    ⚠️ 地下那个 338°（暗紫棕）刻意选在材料空档带里：它是"另一张地图"的身份色，
  //       不该和地表任何一个区撞色相。
  //       （2026-10-02：主角改成近无彩银白之后，区域色**不再需要避开主角的色相** ——
  //         旧注释里"不该和主角的 314° 靠太近"已作废。）
  zoneNear: '#D8C08A',        // h=42° L=69%  浅土黄（最安全）
  zoneMid: '#D6975C',         // h=29° L=60%  土橙
  zoneDeep: '#B4553C',        // h=13° L=47%  锈红（最危险）
  zoneAbyss: '#7E3B4A',       // h=347° L=36% 暗紫红（最深：比深区更暗、色相越过红继续走）
  zoneUnder: '#7A5A66',       // h=338° L=42% 暗紫棕（地下：另一张地图）
};

// `IDENTITY` 里的 `*Rgb` 字段必须是 `'r,g,b'` 串（绘制处要现拼透明度）。
// ⚠️ 和 UI_SKIN 那道自检同一个理由：写成 hex 的话 `rgba(#E07AC8,0.5)` 是**非法颜色**，
//    canvas 会静默保留上一次的 fillStyle —— 不报错、只是颜色不对。
{
  const bad = [];
  for (const [k, v] of Object.entries(IDENTITY)) {
    if (!k.endsWith('Rgb')) continue;
    if (typeof v !== 'string' || !/^\d{1,3},\d{1,3},\d{1,3}$/.test(v.trim())) {
      bad.push(`${k} → ${JSON.stringify(v)}（必须是形如 '224,122,200' 的 RGB 串）`);
    }
  }
  if (bad.length) throw new Error('IDENTITY 的 RGB 串写错了（rgba() 会拿到非法颜色、静默沿用上一次的色）：\n  ' + bad.join('\n  '));
}

// ============================================================
// 动作反馈特效（2026-10-01：核心循环的物理反馈）
// ============================================================
// 为什么要有它：本轮之前，"挖一下"这件事**除了顶部一行横幅文字、零物理反馈** ——
//   而挖掘是全局最高频的动作（每局几十上百次）。贴料、拾取同理，都只有文字。
//
// ⚠️ 这里**只放玩家动作的反馈**（挖掘落尘 / 拾取拖尾 / 贴料落位），
//    灾害特效**不在这里** —— 那三个（impact/bolt/crack）在 render.js 的 `drawEffects`，
//    属于风格 spec §3.1 的"威胁侧（必须严肃、零抖动）"，分类说明钉在 `art.js` 顶部。
//    玩家侧/威胁侧混进同一个绘制函数，art.js 那条"零抖动 ✓"的审计就变成假话了。
//
// ⚠️ 三条硬约束（都有踩坑来源）：
//   ① 粒子的横向偏移**全部来自 `wobble(seed, i, amp)`**（确定性纯函数），不许在绘制里
//      调 `Math.random` —— 每帧随机会把粒子抖成噪点（art.js 的 wobble 注释里有完整来由）。
//   ② 数量必须小：目标是微信小游戏，而挖掘能一秒连点 2~3 下，
//      同屏粒子数 ≈ `n × 未消散的爆发数`，所以档位是 8 / 18，不是几十上百。
//   ③ 颜色必须落在暖色带里（和 OBJ_SKIN 同族）：这些粒子是"岩石碎屑"，
//      不是发光特效 —— 冷色碎屑会在暖棕世界里像贴上去的。
export const FX = {
  // ---- 挖掘落尘：每挖一下从料堆溅出几粒 ----
  // ⚠️ 尺寸是**实测调过一档的**：第一版用 1.4~3.0px，把画布放大 1.6 倍截图看，
  //    7 粒只是几个几乎认不出的模糊小点 —— 而"看得见的反馈才算反馈"。
  //    现在 2.2~4.2px（直径 4.4~8.4px）：在 1280×720 上是一小撮看得出的尘，但不抢戏。
  dust: {
    n: 8, dur: 0.6,
    spread: 34,     // 横向扩散半径（px）：粒子横坐标 = x + wobble(seed,i,spread) × 进度
    rise: 46,       // 向上初速（px/s）
    fall: 150,      // 重力（px/s²）—— 先上后落，落回起点附近刚好消散
    rMin: 2.2, rMax: 4.2,
    color: '#9C8A70',   // 暖灰岩尘
  },
  // ---- 挖到底 / 塌方：更大一团扬尘 ----
  burst: {
    n: 18, dur: 0.95,
    spread: 58, rise: 74, fall: 130,
    rMin: 3.0, rMax: 6.5,
    color: '#8A7A63',
  },
  // ---- 拾取拖尾：几粒碎屑从料堆飞向主角 ----
  gather: {
    n: 6, dur: 0.36,
    spread: 18,     // 出发点的散开量（不然几粒完全重叠、看着像 1 粒）
    arc: 28,        // 飞行弧高（px）
    rMin: 2.2, rMax: 3.8,
    color: '#B5A48D',
  },
  // ---- 贴料落位：一圈冲击环（画的是"这一格补上了"的确认）----
  ring: {
    dur: 0.32,
    r0: 5, r1: 28,
    color: UI_SKIN.ok,
  },
};

// 启动自检：粒子数量 / 寿命 / 半径必须是正数且合理。
// ⚠️ 和"开关类字段不能默认成关"是同一类教训：`n` 写成 0、`dur` 写成负，
//    表现都是**静默**的（什么也不画 / 粒子永远不消失然后越积越多卡死手机）。
{
  const bad = [];
  for (const key of ['dust', 'burst', 'gather']) {
    const f = FX[key];
    if (!(f.n >= 1 && f.n <= 24)) bad.push(`${key}.n = ${f.n}（必须在 1~24：微信小游戏扛不住更多）`);
    if (!(f.dur > 0)) bad.push(`${key}.dur = ${f.dur}（必须 > 0，否则粒子永不消散）`);
    if (!(f.rMin > 0 && f.rMax >= f.rMin)) bad.push(`${key}.rMin/rMax = ${f.rMin}/${f.rMax}`);
  }
  if (!(FX.ring.dur > 0 && FX.ring.r1 > FX.ring.r0)) bad.push(`ring 的 dur/r0/r1 = ${FX.ring.dur}/${FX.ring.r0}/${FX.ring.r1}`);
  if (bad.length) throw new Error('FX 参数写坏了（粒子会不显示 / 或永远不消散把手机卡住）：\n  ' + bad.join('\n  '));
}

// ============================================================
// 地形（2026-09-27 第三轮：**每波程序化生成**，用户要求"像重生细胞那样"）
// ============================================================
// 为什么再重做：前两轮的地形是"固定的数学函数"，虽然把起伏从 38px 加大到了 192px，
// 但**每波、每局都一模一样** —— 走过一次就背下来了，探索退化成"按最短路径跑"。
//
// 现在的做法（每波开始用种子重新生成，见 world.js 的 genTerrain）：
//   · 从庇护所**往外分段**：每段宽 `segW` 随机，每段的高度**有升有降**（`±maxDelta` 随机）
//   · 方向带两个偏置：① 越接近上/下边界越容易往回走（否则会长期贴边成高原/平原）；
//     ② 叠一点 `trend` 向上趋势，让远处平均略高（保留"越远越险"的感觉，但不是一条单调的坡）
//     ⚠️ 这一条是用户反馈"地形一直是上坡"之后改的：第一版每段只加不减，整张图就是一条斜坡。
//   · 庇护所 ±`flatRadius` 内压平（否则台地会把庇护所埋进土里）
//   · ⚠️⚠️ 2026-10-03 **改了**：级与级之间由"垂直岩壁（阶跃）"改成**斜坡**
//     （用户："不要明显的阶梯感，要那种坡度上升和坡度下降的地形"）。
//     于是地形改成**斜坡 + 偶尔一道垂直岩壁**：大部分是坡（能走），少数是坎（要跳）。
//     代价是**原来那条"阶跃挡人"失效了**（贴地吸附每帧只升 1~2px，永远小于 `stepUp`）
//     → 挡人判定换成**坡度**：`player.move()` 量"前方 `slopeProbe` 内的坡度"，超过 `maxSlope` 才挡。
//     ⚠️ `RULES.stepUp` **保留**（岩桥的 `branchDownGap` 还在引它），只是不再管地形。
//   · 高度始终夹在 `0 ~ maxRise` 之间（不低于基准、也不顶到屏幕上方压住 HUD）
//
// ⚠️⚠️ `maxDelta` **必须 ≤ 跳跃极限（约 63px）** —— 这是"**不会生成死图**"的唯一保证：
//    只要每一级都跳得上去（升）或走得下去（降），玩家就一定能从庇护所一路走到世界两端。
//    如果哪天把它调大了，就必须补一套真正的可达性搜索（不能只靠这条参数）。
// ⚠️ 这条同时**推翻了原来"地形是确定性函数、可记忆"的设计**（旧理由见 docs/01 9.1⑧）：
//    现在用"每波都是陌生地图"换探索感，代价是"背地图"这件事没有了 —— 这是用户拍板的取舍。
export const TERRAIN = {
  flatRadius: 350,        // 庇护所附近这么大范围压平
  // ⚠️ 2026-09-27 第四轮：180~280 → **90~180**（用户要"增加地形复杂度"）——
  //    台阶更碎、台地更小，"大块台地"变成"层层小台"，走起来的起伏更密。
  segW: [90, 180],        // **坡段**的宽度（随机范围）
  maxDelta: 48,           // 高差上限（必须 ≤ 跳跃极限 63）
  // ---------- 坡与坎（2026-10-03 新增，见文件顶部"改了"那段）----------
  // 地形只有两种段，靠**段宽 + 坡度**分开（坡度 = 高差 / 段宽）：
  //   · **坡段**（宽 `segW`）：高差 ≤ `maxDelta` → 实际坡度 ≤ 48/90 = **0.53（28°）**，能走
  //   · **坎段**（宽 `steepSegW`，很窄）：高差取满 → 坡度 ≈ `steepSlope` → **视觉上就是一道垂直岩壁**，要跳
  // ⚠️ 判定阈值 `maxSlope` 只要**卡在两者中间**就行：坡段最高 0.53、坎段最低 ≈ `steepSlope`＝6。
  //    取 **2.0（≈63°）** —— 用户的原话是"接近 80 度或 90 度的陡坡，这种要跳"。
  maxSlope: 2.0,          // 走不上去的坡度阈值（≈63°）
  // ⚠️ 坎的目标坡度 = **80.5°**。而 `player.move()` 量坡度的前瞻距离 `slopeProbe` 只有 6px ——
  //    必须**短于坎的宽度**（`maxDelta / steepSlope` = 48/6 = **8px**），否则旁边的坡会把它平均掉、坎就失效。
  steepSlope: 6.0,
  // 做坎所需的最小空间：`maxDelta` 取不满时（贴着 0 / maxRise）就不做坎、退化成坡 ——
  // 否则会造出一道"半吊子的斜坎"，正好落进判定阈值附近。
  steepMinRise: 20,
  steepChance: 0.25,      // 每段有多大概率是"坎"
  slopeProbe: 6,          // `player.move()` 量坡度时的前瞻距离（px）—— 见上面那条 ⚠️
  maxRise: 260,           // 全局最高（世界两端最多抬这么高）
  trend: 0.15,            // 向上趋势偏置：0 = 完全对称的起伏；0.15 = 平均缓慢升高
  // 地面比基准高这么多就算"高处" → 可以躲地陷
  highGround: 30,
  // 岩棚（突出岩架）：站到它下面就能躲陨石。
  // ⚠️ 2026-09-27 第四轮：从"写死两个坐标"改成**每波生成**（见 world.js 的 genShelves）——
  //    世界宽度一直在变，写死坐标每次都要手算；而且它必须落在"玩家真能走到的地方"。
  shelfCount: [2, 3],     // 每侧数量
  shelfW: 104,
  shelfH: 76,
};

/**
 * 悬空岩桥 / 高台（2026-09-27 新增；同日改成**每波程序化生成**）。
 *
 * ⚠️ 这是本作第一次有**可站立但不是地面**的东西。原来看上去像平台的"岩棚"
 *    （TERRAIN.shelves）其实只是**遮挡判定**，脚踩不上去 —— 真正的平台要满足：
 *    ① `player._vertical` 能落在它顶面上；② 从下方跳上来时能穿过去（单向平台）。
 *
 * ⚠️⚠️ 四条硬规则（前三条是被用户反馈打出来的，第四条是"像重生细胞"那一轮加的）：
 *  ① **相邻桥要么"能直接走上去"、要么"留空隙让人跳"** —— 用户反馈过
 *     "空中平台之间的跳跃还是不方便"。第一版是"留 50px 空隙 + 高差 40px 让玩家跳过去"：
 *     虽然算出来能跳（余量 22px），但要求玩家在边缘按对时机起跳、空中还得保持方向，
 *     跳早了就掉下去。→ 现在级差小时**首尾相接（直接走上去）**、级差大时才留空隙。
 *  ② **任何一条桥都必须在"地面跳不到"的高度**（`gen.minClear` > 跳跃极限）——
 *     否则上层路线根本不需要升降台。这条由 `genBridges` 生成时**逐条校验**，不够高就抬。
 *  ③ 桥面只按顶面判定（单向平台），所以"从桥上跳下来"不需要额外的下跳键。
 *  ④ **`list` 是运行时数据**：每波由 `world.js` 的 `genBridges()` 重新生成并写入。
 *     config 里只放**生成参数** —— 在这里手写桥会被覆盖掉。
 */
export const PLATFORMS = {
  thickness: 18,     // 画出来的厚度（纯视觉；落地判定只看顶面）
  // 📊 上层废墟的掉落表加成：同样挖第 1 层，高处的料**往后翻 3 张表**。
  //    这是"上去值得"的唯一兑现，也是让"坐升降台"划得来的东西。
  // ⚠️ 为什么是 3 而不是 1~2：实测发现近区**前 3 张表的结构件候选全是虫级**（t1_hard/t1_soft），
  //    翻 2 张等于没翻 —— 玩家坐升降台上去挖第一层，拿到的和地面一模一样。
  //    翻 3 张才会开始出现蛇级（近区从第 4 张表起混入 t3_hard）。
  tableBonus: 3,
  // ---------- 上层岩桥的废墟类型权重（2026-09-28 定案：**没有引怪型**）----------
  // 用户要求："把空中的引怪性去掉"。三条理由（① 是查代码后才确认的，不是想当然）：
  //   ① **怪够不着你，但伤害够得着** —— 怪物只走地面（贴 `terrainY`，没有平台概念），
  //      而当时伤害判定只看 `|Δx| < contactRadius`、**完全不看 y**（monsters.js 的 `touching`）。
  //      所以在桥上挖引怪堆 = 把地面怪吸到你正下方：它上不来、你也没法跳下去打，
  //      但你站在桥面上照样掉血 —— 玩家只看到"我在高空，血却在掉"，无从理解、只能当成 bug。
  //      ⚠️ **2026-09-29：这条根因已经修掉了**（新增 `MONSTERS.reachY`，站高处就够不着你）——
  //         但**"空中没有引怪型"这个决定保持不变**（理由 ②③ 仍成立），而且**将来也没必要加回来**：
  //         加回来只会把地面的怪**白引到正下方**（够不着你、你也打不了它），纯属浪费。
  //      ⚠️ 这也是一堂课：2026-09-28 那次只**绕开了触发路径**（去掉空中引怪型）、没修判定本身，
  //         结果 09-29 用户玩的时候换了条路径又撞上（怪自己游荡到正下方）。修 bug 要分清
  //         "我在修机制"还是"我在绕开它"——绕开之后必须留一条明确的"未修根因"记录。
  //   ② 引怪型是三种里**唯一挖完不消失、可反复挖**的（可持续产出）。空中要的是"越值钱越不稳定"，
  //      不是"可持续刷"。去掉后上层废墟是一次性产出（稳 1~2 块 / 易塌 4~9 层）。
  //   ③ 上层的风险该来自"易塌"（亏一半 + 被埋 12s），不该来自"看不见来源的掉血"。
  // ⚠️ 只去掉**空中**：地面/地下各区仍按 `ZONES[].typeWeights` 出引怪 ——
  //    全局引怪比例、龙级产出速率（实测 83% 的龙级来自引怪型）都**不受影响**。
  // 权重保持原来的 3:5 相对比例（只是不再把引怪的 2 份算进去）。
  typeWeights: { stable: 3, caveIn: 5 },
  // ---------- 生成参数（每波用种子重新生成，见 world.js 的 genBridges）----------
  gen: {
    perSide: [2, 4],        // 每侧**主干**桥数（首尾相接的阶梯长廊，保证走得通）
    w: [200, 320],          // 主干桥宽（随机）
    yNear: [250, 275],      // 最靠庇护所那条桥的高度（随机；y 越小越高）
    stepNear: [18, 26],     // "能走上去"的级差（≤ RULES.stepUp，相接）
    stepFar: [34, 58],      // "必须跳"的级差（> stepUp 且 ≤ 跳跃极限，留空隙）
    gapFar: [40, 90],       // 级差大时的水平空隙（要跳多远）
    minClear: 78,           // 桥面离**正下方的地面**至少这么高（> 跳跃极限 63 → 地面跳不上）
    yMin: 205,              // 桥最高不能高过这里（免得顶到画面上方）

    // ---------- 网络化：从主干上分叉出"支桥"（2026-09-27 第四轮）----------
    // 为什么加：主干只是一条"从庇护所往外、越外越低"的阶梯 —— 上层自己**没有路线选择**。
    // 分叉出支桥之后，上层也有"这条通到哪、要不要绕"的取舍（支桥上同样有废墟）。
    branch: [1, 2],         // 每侧支桥数量（随机）
    branchW: [140, 240],    // 支桥宽度（比主干窄，一眼能区分主次）
    branchUp: 0.6,          // 支桥长在主干**上方**的概率（上方要跳上去、下方能走下去）
    branchUpGap: [30, 55],  // 在上方时的高差（必须 ≤ 跳跃极限 63，否则上不去）
    branchDownGap: [18, 26],// 在下方时的高差（≤ stepUp 26 → 直接走下去）
  },
  list: [],   // ← 由 world.js 每波生成填充，别手写
};

/**
 * 遗迹升降台（2026-09-27 新增，用户选定："通过特殊的方式把人物带到更高的地方去探索"）。
 *
 * 规则：
 *   · **站在台上**（±`standRadius` 且在地面）才能启动 —— 点它 → 消耗 **1 件结构材料**
 *   · 消耗的是背包里**档次最低**的那件（防止把辛苦挖来的龙级料误吃掉）
 *   · 上升耗时 `seconds`，期间不能移动/跳跃/挖掘 —— 是个实打实的风险窗口
 *   · 落点 `to` 必须是某条桥的顶面（否则会直接掉下来）
 *
 * ⚠️ **`list` 是运行时数据**：每波由 `world.js` 的 `genLifts()` 重新生成
 *    （每侧一座，放在某条桥的**正下方**，落点 = 那条桥的顶面 → 天然不会落空）。
 */
export const LIFTS = {
  standRadius: 46,   // 站在多远以内算"在台上"
  seconds: 4,        // 上升耗时
  cost: 1,           // 消耗几件结构材料
  list: [],          // ← 由 world.js 每波生成填充，别手写
};

/**
 * 隐藏区：**碎石堆**（2026-09-27 新增，用户要求"像重生细胞那样"要有隐藏区）。
 *
 * 设计取舍：**不新增操作** —— 打开它用的就是"点一下、挖几下"这套现有交互，
 * 玩家不需要学新东西（手机上也少一个按钮）。
 *
 * 规则：
 *   · 每波程序化放 1~2 个（只在深区/中区 —— 值得跑过去才有意义）
 *   · 点它 → 消耗"力量"（要挖 `power` 下，每下占一个挖掘硬直）→ 归零就**打开**
 *   · 打开后变成一个**富料堆**：掉落表后翻 `HIDDEN.tableBonus` 张（比"上层废墟"的 3 还高）
 *
 * ⚠️ 为什么加成要比上层废墟更高：上层的门槛是"消耗 1 件结构材料坐升降台"，
 *    而这里是"先找到 + 挖 3 下 + 每下都花时间" —— 找 + 挖的代价更隐蔽，收益要更明显才值。
 */
/**
 * 龙级废墟（2026-09-27 第五轮，用户定案）。
 *
 * 用户原话："改为空中和地下都有分布，但是出现的概率减低，大概 20% 左右；
 *          还有碎石堆富料堆的出现概率也减低，大概 10% 左右"。
 * 澄清后确认的三个点：
 *   ① 20% = **"20% 的料堆是龙级废墟"**（不是"每件材料 20% 概率出龙级"）；
 *   ② 碎石堆 10% = **每波只有 10% 概率生成**；
 *   ③ 空中（岩桥上层）和地下**一样**，不搞两套稀缺度。
 *
 * 为什么要从"表权重"改成"料堆级抽签"：
 *   旧机制（靠 `bonus` 顶到第 6 张表、龙级占 50% 权重）的问题是——它只控制**期望值**：
 *   玩家挖够件数就必然拿到，龙级于是变成"体力活"。改成"哪些料堆是龙级废墟"之后，
 *   挖开一个新废墟时会真的**期待**（"这个会不会是龙级废墟"），而不是心算概率。
 *
 * ⚠️ 龙级废墟**故意不做视觉区分**（和"所有料堆外观一样、挖出前不知道是什么"一致）——
 *    否则玩家会只挑龙级废墟挖，产出立刻失控（估算过：那样一局会从 ~25 件直接冲到 80+ 件）。
 *
 * ⚠️ `rate` 的取值是反推出来的（目标：一局 12 波约 10~15 块**软**料，
 *    对应"5 块达标 / 18 块顶配"这条既有梯度，见 docs/01）：
 *    ⚠️⚠️ 2026-09-27 第五轮补记：把"一局 N 件"当成**全图总量**去核，会发现对不上 ——
 *    旧配置全图是 t7 **161 件/局**（软 80），而 docs/01 写的"约 15 件/局（软 ~7.5）"
 *    是**真人估算**（按时间模型只能收集全图的 ~9%）。**两个口径别混用**，
 *    比较新旧时必须用同一个（下表一律是"全图挖穿"的上界）。
 *
 *    实测（60 局 × 12 波 × 两层，全部料堆挖穿）：
 *    | 配置 | 全图产出/局 | 其中 t7 | 软 t7 | 真人估算 t7（软）|
 *    |---|---|---|---|---|
 *    | 旧：4~9 层（均值 6.5）、第 3 层起、rate 0.35 | 5451 | 161 | 80 | ~15（7.5）|
 *    | 第五轮：1~3 层（均值 1.6）、第 1 层起、rate 0.35 | 1586 | 78 | 39 | ~7（~3.6）|
 *    | 第六轮：按类型分档（均 5.13 层）、第 1 层起、rate 0.35 | 3965 | 196 | 97 | ~18（9.0）|
 *    | **第六轮续（当前）：按类型分档、第 3 层起、rate 0.40** | 3951 | **121** | **61** | **~11（5.7）** |
 *
 *    ❗ 2026-09-27 第六轮续（用户定案"龙级获得率还需要降低"）：把 `minDepth` 从 1 **改回 3**、
 *      `rate` 0.35 → **0.40**，合起来把龙级压到真人估算 **约 11 件/局（软 ~5.7）**：
 *      · 达标线（5 块）**还宽裕**，顶配（18 块软料）基本不可能 —— 正是用户要的"很难但够得着"。
 *      · 顺带修掉一个语义怪事：`minDepth` 停在 1 时**稳固型那 1~2 层也会出龙级**
 *        （实测占 t7 的 10%）。回到 3 之后**稳固型再也不会出龙级** ——
 *        "龙级只能从深挖里来"这才成立。
 *      · ⚠️ 注意两个旋钮是**乘起来**的关系，别只调一个：`minDepth` 砍掉的是"够深的层数"
 *        （稳固型直接归零、易塌/引怪只剩 2~7 层），`rate` 才是"每层出多少"。
 *        只把 `rate` 从 0.35 抬到 0.40（minDepth 不动）反而会让龙级**变多**。
 *      · 标定扫描（minDepth 3、chance 0.2，都是实测）：
 *        rate 0.30 → 全图 89（软 45）/ 真人 ~8；**0.40 → 121（软 61）/ ~11**；
 *        0.50 → 154（软 76）/ ~14；0.70 → 208（软 104）/ ~19。
 */
export const T7_RUIN = {
  chance: 0.2,          // 有资格的料堆里，20% 是"龙级废墟"（只有它们会吐龙级）
  // 2026-09-27 第五轮：**3 → 1**（当时所有废墟都缩成 1~3 层，3 会让龙级直接归零）；
  // 第六轮：部分废墟回到 4~9 层后又**1 → 3**（回到"第 3 层起才吐"，稳固型彻底出不了龙级）。
  // 历史一圈走下来说明这个值其实是**跟着"废墟能挖多深"走的** —— 改产出层数时必须回来看它一眼。
  minDepth: 3,          // 第 3 层起才可能吐（浅层白拿太便宜，也和"越挖越危险"挂钩）
  rate: 0.40,           // 龙级废墟在"够深的层"里，每层 40% 出龙级；其余层走正常掉落表
  richRate: 0.8,        // 碎石堆的富料堆专用：它每波只有 10% 概率出现，稀有度配得上高概率
  eligibleZones: ['abyss'],   // 地面上的"有资格区域"；**上层岩桥废墟**与**地下**在生成时单独标记
  // ⚠️ 2026-09-28（材料表扩容到 125 种）：龙级从 2 种扩到 **8 种**，这里要写清"哪 5 种能挖到"。
  //   龙级 8 = **危险废墟 5 种（板/膜/镜/匣/翼，都是纯取向）** + **蛟×蛟 3 种（砖 / 板砖 / 膜砖，
  //   只能合成）**。两组**必须互斥**，否则凑不出 8：
  //     · 砖（t7_tough）是"耐久专精"，刻意做成合成专属（废墟挖不到）
  //     · 板 / 膜 保持"既能挖、也能合成"（它们的配方是 t5_板+t5_砖 / t5_膜+t5_砖）
  pool: ['t7_hard', 't7_soft', 't7_gloss', 't7_seal', 't7_light'],
  // ⚠️ 表里抽到 t7 时降级成什么。**只有普通废墟会走这条路**（"龙级废墟"那条分支直接给 pool）。
  //   为什么要有它：注释早就写明"普通废墟永远不会吐龙级"——这条是**硬保证，不依赖表怎么改**。
  //   降级目标按"该取向最贴哪条灾害线"落到对应蛟级：镜/匣 走穿墙线（膜打底）、翼 走破门线（砖打底）。
  // ⚠️⚠️ 2026-09-28：**掉落表里已经不该出现 t7 了**（有断言拦着，见下面的掉落表自检）——
  //   因为"料堆级抽签"接管了龙级之后，表里的 t7 只会被降级，等于把权重白送给 t5。
  //   所以下面这张 `downgrade` 表**现在走不到**，保留它只为两层兜底：
  //     ① 万一有人放宽/删掉那条断言、或者手工往表里加了 t7；
  //     ② ⚠️ 更关键：`t7_gloss / t7_seal / t7_light` 的降级目标是**混合料**（`t5_soft_gloss` 这种）——
  //        真让它们走通，废墟就会**直接掉混合料**，而"混合料只能靠合成得到"是另一条硬规则，
  //        且那条断言**看不到运行期降级的结果**。所以要拦的是"表里出现任何 t7"，不只是硬/软两种。
  downgrade: {
    t7_hard: 't5_hard', t7_soft: 't5_soft',
    t7_gloss: 't5_soft_gloss', t7_seal: 't5_soft_seal', t7_light: 't5_tough_light',
  },
};

export const HIDDEN = {
  chance: 0.1,          // 每波**只有 10% 概率**出现（2026-09-27 用户要求："出现概率降到 10% 左右"）
  count: [1, 1],        // 出现了就是 1 个（原本每波必有 1~2 个）
  power: 3,             // 要挖几下才打开
  tableBonus: 5,        // 里面料堆的掉落表加成
  minGap: 70,           // 与已有料堆的最小距离（免得和废墟挤在一起、点不清）
  // ⚠️ 2026-09-27 第六轮续：**2~3 → 3~3**。富料堆被定为"龙级废墟 + 出率 0.8"，
  //    而 `T7_RUIN.minDepth` 回到了 **3** —— 原来 2 层的那些**永远够不着第 3 层**，
  //    等于"挖了 3 下打开碎石堆，结果一块龙级都没有"（`richRate` 静默失效）。
  //    固定 3 层之后，它每次都能把龙级吐出来，稀有度配得上"每波只有 10% 概率出现"。
  rewardDepth: [3, 3],  // 里面料堆的层数（随机）
  w: 46,                // 绘制/命中尺寸
  // ⚠️ 2026-10-02：`h` 从 54 改成 **41** —— 碎石堆换成像素画贴图后，素材的宽高比是 **1.13 : 1**
  //    （46 宽 → 41 高）。留 54 的话，贴图会**贴底缩在下半部、上面空 13px**，而进度裂纹和
  //    "碎石堆 N" 标签都是按 `h` 定位的 → 裂纹会**浮在石堆上方**（截图里一眼可见的错位）。
  //    · 底边不动（`y = h.y - h + 14`，`y + h` 恒等于 `h.y + 14`）→ 石堆仍然站在地上，只是变矮。
  //    · 牵连面两处，都已核对：`main.js` 的点击判定（`w+12 × h+12`，66 高 → 53 高，仍然好点）、
  //      `render.js` 的绘制与裂纹坐标（都按 `h` 算，自动跟着走）。
  h: 41,
};

/**
 * 小地图（2026-09-27 新增，用户要求）—— HUD 下方的一块缩略图。
 *
 * 显示：地形轮廓 / 已探索范围（逐步点亮）/ 废墟 / 升降台 / 碎石堆 / 庇护所 / 玩家。
 * ⚠️ 位置挑在**屏幕左下、HUD 之下、动作按钮之上**的空档（y 250~342）：
 *    那块平时只压着"天空/背景"，不会挡地形和人物。人物跑到世界最左端时屏幕位置会靠近它，
 *    所以面板做成**半透明**，压住了也还看得见。
 */
export const MINIMAP = {
  x: 16, y: 250, w: 380, h: 92,
  pad: 6,
  lineH: 46,        // 地形折线的绘制高度（越小越平）
};

/**
 * 隧道（2026-09-27 第四轮新增，用户要求"增加路径选择"）—— 连接**近区 ↔ 极深区**的捷径。
 *
 * 为什么必须有它：世界扩到 4800 之后，跑到极深区单程约 15 秒、**满载回程 40 秒** ——
 * 一趟 55 秒，180 秒准备期只够跑 3 趟，极深区基本玩不到（见 WORLD 的注释）。
 * 隧道把这段路压成"走到洞口 + 1.5 秒过渡"，于是"去最远处"重新变成一个**可选项**。
 *
 * ⚠️ 它本身**就是"路径选择"**：
 *   走路（慢，但沿途能顺手捡料、能挖到近/中区的东西）
 *   vs 走隧道（快，但**跳过了沿途所有废墟** —— 到极深区时背包还是空的）
 *   → 两种走法各有代价，不是"有更好的一个"。
 */
export const TUNNELS = {
  w: 52, h: 30, hitPad: 8,
  transition: 1.5,        // 过渡时长（渐黑 → 跳过去 → 渐亮）

  // ⚠️⚠️ 2026-09-27 第四轮·再改（用户原话："如果玩家很轻松就来到深处，那他们就不会去近处了，
  //      毕竟深处材料等级高；我觉得传送位置可以随机一点，而且隧道可以跟着地形的改变出现或者消失"）
  //
  // 这说的是一个**真问题**：如果隧道稳定存在、位置固定、又直通高档料区，
  // 那"就近取材"和"越远越险"这两条设计就一起失效 —— 玩家只会永远走隧道。
  // 所以三条一起改（全部是"削弱确定性"）：
  //   ① **每侧独立 `sideChance` 概率才有**：于是"这一波有没有捷径"本身是运气，
  //      两波都可能没有（0.4 × 0.4 = 16%）。
  //   ② **洞口位置在很大范围内随机**（不再是固定距离）→ 玩家每波都得重新找。
  //   ③ **跨度小于 `minSpan` 就直接放弃这条**：免得出现"隧道只省几步路"的廉价品，
  //      也保证"它一旦存在，就真是一条值得钻的路"。
  // ⚠️ 2026-09-28 第三改（用户："为什么我感觉通往深处的隧道出现的概率很高" → 定案 **0.6 → 0.25**）：
  //    上一版 0.6/侧 的实际结果是 **84% 的波次都有隧道**（1 − 0.4²），也就是"捷径是常态"，
  //    和上面 ① "这一波有没有捷径本身是运气"的原意正好相反 —— 用户体感比设计意图更准。
  //    改成 0.25 之后：**至少一条 43.75%** · 两侧都有 6.25% · **一条都没有 56.25%**（0.75²）。
  //    ⚠️ 为什么不建议更低（≤0.15）：隧道是"极深区能不能被玩到"的前提之一 ——
  //       世界 4800 宽，走到极深区单程约 15 秒、满载回程 40 秒，没有捷径时那一区基本玩不到。
  //    实测（无头 2000 波，走真实生成逻辑 genTunnels，见 docs/01 9.1）：
  //      **至少一条 44.5% / 两侧都有 6.7% / 一条都没有 55.5%**（理论 43.75 / 6.25 / 56.25）✓
  sideChance: 0.25,       // 每一侧本波生成隧道的概率
  aDist: [600, 1300],     // 洞口 A：近区外半 ~ 深区（随机）
  bDist: [1700, 2300],    // 洞口 B：深区外侧 ~ 世界最外缘（随机）
  minSpan: 700,           // 两端距离小于这个数就不要这条（太廉价的捷径没意义）
  // ⚠️ 隐蔽：走进 `revealDist` 之内才"看清"这是洞口（发光 + 文字）。
  //    远看只是一个**暗色凹坑**（几乎融进地形），所以"找到隧道"本身也是一次探索。
  //    但**不做到"完全看不见"**：走近必须显现（本项目反复写过"看得见的机会才叫设计"）。
  revealDist: 220,
  list: [],               // ← 由 world.js 每波生成填充（**可能为空**，别假设一定有）
};

/**
 * 天然石台（2026-09-27 第四轮新增，用户要"三层立体"）——
 * 在**地面与悬空岩桥之间**再插一层可站立的小平台（天然岩架，不是人造桥）。
 *
 * 与岩桥的区别（这是它能增加复杂度的原因）：
 *   · 岩桥是一条**连续长廊**（保证走得通），石台是**离散的小块**（每块 90~160px）
 *   · 石台**故意做成"跳得上去但不一定连得起来"** → 有的石台能连成一条攀爬路线，有的只能跳一下够个高
 *   · 高度在地面之上 `minClear`~`maxH`（所以从地面跳不上去，得先跳上台地/用石台接力）
 *
 * ⚠️ 它们**不承诺连通** —— 玩家要自己判断"这块能不能跳过去"。这是"复杂度"的来源，
 *    但每块都保证"从它正下方的地面跳不到"（否则石台就退化成普通台阶了）。
 */
export const LEDGES = {
  count: [6, 10],         // 每侧数量（随机）
  w: [90, 160],           // 每块宽度
  minClear: 90,           // 离正下方地面至少这么高（> 跳跃极限 63 → 地面跳不上）
  maxClear: 210,          // 最高也就离地这么多（再高就撞上岩桥层了）
  list: [],               // ← 由 world.js 每波生成填充
};

/**
 * 地下世界（2026-09-27 第四轮，用户要求"开拓地下世界"）。
 * 路线：**分层**（地面放地穴入口 → 点它切到地下层）——
 * 当时评估过"把世界向下挖 + 相机跟随 y"，代价是底部背包 UI 会挡住地下视野、光照要重做，改动太大。
 *
 * 地下与地面只差这四条，其余全部复用：
 *   · 地形：另一套（每波重新生成），视觉上是"洞窟"（有岩顶、更暗）
 *   · 料：**统一给"深区待遇"**（用深区的表 + `tableBonus`）→ 地下处处都能挖到深区档次的料，
 *     **不用跑远**，这就是它的"高回报"。
 *     ⚠️ 2026-09-28 改：原来是"用极深区的表 + bonus 6"，那会走到"bonus 顶到表尾"的坑（见下面的注释）。
 *   · 光照：手电筒半径 × `lightScale`（更暗 = 更慌）
 *   · **只在准备期能下去**：灾害期入口关闭，"灾害来了地穴会塌"
 *     ⚠️ 这一条同时解决了一个设计问题：否则"一下去就完全躲开灾害"，整个灾害期就没压力了。
 *     （它也让"地下玩家不会被灾害打到"自动成立 —— 因为那时他根本不可能在地下）
 *
 * ⚠️ 实现上是**两个 World 实例 + 一个"当前层"指针**（见 world.js 的 setLayer）——
 *    撒点、物理、渲染都不用改。
 */
export const UNDERWORLD = {
  entranceCount: [1, 2],       // 每层的入口/出口数量（地面=地穴入口，地下=上行口）
  entranceDist: [450, 2100],   // 距庇护所的距离范围（随机：近处远处都可能）
  // ⚠️⚠️ 2026-09-28：**6 → 0**（这是修 bug，不是调参）。
  //    `digOnce` 取表的公式是 `idx = min(depth + bonus, 表数) - 1` ——
  //    **bonus ≥ 表数(6) 时它恒等于"最后一张表"**，也就是地下**每一层（含第 1 层）**
  //    都在用"极深区最顶层"那张表。实测（60 局、真实 digOnce）的后果：
  //      · 地下产出占全部结构件的 **47%**，其中 **90% 是蛟级** → 全局蛟级占比 **57%**；
  //      · 还有第二层原因：那张表的权重是 `t5 4/10 + t7 4/10`，而 2026-09-27 把龙级改成
  //        "料堆级抽签"之后，**非龙级废墟从表里抽到的 t7 会降级成 t5**（`T7_RUIN.downgrade`）
  //        → 对 80% 的废墟来说那张表实际是 **8/10 = 80% 蛟级**。
  //        （旧机制下"表权重"就是龙级来源，它是 50% 龙级；改成抽签后没人再看过这张表的构成。）
  //    改法：地下改用**深区的表 + 0 加成**。实测全局蛟级 57% → **28%**（与地面 27% 齐平）、
  //      龙级 88 → **92 件/局**（不动已标定的供给）、均档 4.12 → 3.48。
  //      地下的"高回报"由"处处都是深区待遇、不用跑远"承担；塌方使用下方独立地下曲线。
  //    ⚠️ 别再往上调：**`bonus + 1 > 表数 - 1`** 时第 1 层就顶到最后一张表，深度梯度静默消失
  //       （下面有启动自检拦这一条）。
  tableBonus: 0,
  t7Chance: 0.10,
  caveInByDepth: [0.06, 0.10, 0.16, 0.24, 0.34, 0.46, 0.58, 0.70, 0.80],
  lightScale: 0.5,             // 地下手电筒半径倍率（更暗）
  ceilingY: 210,               // 洞顶（世界 y）—— 纯视觉，画一条岩顶

  // ---- 地下中段补点（2026-09-27 用户："随便把地下的空地补好吧"）----
  // 背景：两层**共用同一套撒点区间**（近区 1700~2060 / 2740~3100），所以庇护所正下方那 680px
  //   不属于任何区 → 地面上那里是庇护所自己的院子（故意不长废墟），地下也就跟着空着；
  //   再加上"庇护所附近压平"被照抄到地下（见 world.js 的 genTerrain）→ 那一段还是**平的**。
  //   用户原先说"留给以后的怪物巢穴"，现在改成**直接补上**。
  // ⚠️ 只在**地下层**补（地面上那一段是庇护所的地盘，补了会堵住出门的路）。
  // ⚠️ 类型抽签沿用**近区**那套权重（中段与近区等距，本来就是"家门口"的地带）。
  centerFill: {
    perSide: 2,          // 中轴左右各 2 个（共 4 个）
    dist: [70, 330],     // 离中轴的距离范围：避开 ±70 的轴心，且不超出中段（±340）
  },
};

export const JUMP = {
  speed: 430,        // 起跳初速度（像素/秒）
  gravity: 1450,     // 重力
  minInterval: 0.18, // 两次起跳的最小间隔（防止连点飞天）
};

// 跳跃 / 手电筒的屏幕按钮（2026-09-26）
// ⚠️ 这两个动作**必须**有屏幕按钮：这是微信小游戏，手机上没键盘，
//    只绑快捷键等于这两个功能在真机上不存在（之前"结算页只能按 R"就踩过这个坑）。
// 位置选在左侧、HUD 之下、背包之上的空白带，避开世界里的可点对象。
export const ACTION_BTN = { size: 60, x: 22, jumpY: 420, lightY: 492 };
export function jumpBtnRect() {
  return { x: ACTION_BTN.x, y: ACTION_BTN.jumpY, w: ACTION_BTN.size, h: ACTION_BTN.size };
}
export function lightBtnRect() {
  return { x: ACTION_BTN.x, y: ACTION_BTN.lightY, w: ACTION_BTN.size, h: ACTION_BTN.size };
}
/**
 * 手电筒：照亮半径 + 开/关的过渡时间。
 *
 * ⚠️ `transition` 为什么必须有：原来开/关灯是**瞬间跳变**的 —— 点一下「灯」，
 *    可见范围在一帧内从 84px 跳到 250px。而"可见度"本身是这个游戏的核心机制，
 *    它"啪"地一下变完，玩家看到的是"闪了一下"，而不是"我把灯打开了"。
 *    （和层间过渡是同一个病的两种表现：**瞬变看不见，会被当成卡顿或 bug**。）
 * ⚠️ 过渡必须同时作用于**三样东西**（半径 / 黑幕中段浓度 / 中心暖光强度），
 *    见 main.js 的 `lightK` 与 render.js 的 `drawDarkness` —— 只过渡半径的话，
 *    亮度还是"啪"一下，等于白做。
 */
export const LIGHT = { onRadius: 250, offRadius: 84, transition: 0.35 };

/**
 * 层间过渡（地穴口 / 上行口）时长：渐黑 → 换层 → 渐亮。
 *
 * ⚠️ 为什么必须有：换层是一次**瞬移** —— 人到另一个坐标、换到另一张地图、换一批怪物。
 *    不做过渡的话画面在 1 帧内整个换掉，玩家只会以为"画面闪了一下 / 我是不是卡了"。
 * ⚠️ 隧道早就有这套机制（`TUNNELS.transition = 1.5`），这里补的是**唯一还没做过渡的路径**。
 *    （升降台**不需要**：它本来就是 4 秒的 from→to 动画，见 `player.startLift`。）
 * ⚠️ 取值比隧道短（0.8 vs 1.5）：地穴口是"往下走一层"，不是"钻过一条长通道"。
 */
export const LAYER_FADE = 0.8;

// ---------- 左侧状态面板的几何 ----------
// ⚠️ 面板尺寸必须**只在这里定义一次**：render 负责画、main 负责命中判定，
//    两边各写一套坐标就一定会漂移 —— "提前开波"的按键提示漂掉就是这么来的（见 docs/04）。
// h: 212 → 224（2026-09-26）：底部要多一行"待放空位"，原高度只够到告警行（基线 192）。
export const HUD = { pad: 16, w: 430, h: 224 };
/** 状态面板"展开 + 套拖动偏移"矩形 */
function hudPanelOpenRect() {
  return uiOffsetRect({ x: HUD.pad, y: HUD.pad, w: HUD.w, h: HUD.h }, 'hud');
}

/** 状态面板矩形：**先算基准、再套拖动偏移**；收起时直接返回标签矩形（见 UI_LAYOUT / UI_CHROME）。
 *  ⚠️ 这样 render 的绘制与 main 的命中都从同一个函数取矩形，收起后不会各画/各判一套。 */
export function hudPanelRect() {
  return UI_LAYOUT.hud.collapsed ? uiLabelRect('hud') : hudPanelOpenRect();
}

/**
 * "提前开波"按钮 —— 2026-09-26 用户要求："把 HUD 那行提示本身做成可点"。
 *
 * ⚠️ 为什么**必须**有它：Enter 只有键盘有，而目标是微信小游戏（手机上没键盘）。
 *    只绑快捷键盘 = 这个机制在真机上不存在 —— 和当年"结算页只能按 R"是同一类坑。
 *    （「跳」「灯」也是为此才有屏幕按钮的，见上面 ACTION_BTN 的注释。）
 *
 * 位置：它和上面那行"本波灾害"**共用一个区块**。面板很密，"本波灾害"（基线 82）和
 * 原来那行提示（基线 102）之间只剩约 5px，单独把提示做成按钮只有 18px 高、手机点不中；
 * 两行合起来才有 42px。所以准备期这块整体画成一个按钮，灾害期只画成普通文字。
 */
export const SKIP_BTN = { x: HUD.pad + 185, y: HUD.pad + 46, w: HUD.w - 185 - HUD.pad, h: 42 };
/**
 * "本波灾害：…"这一行的左缘（**面板内偏移**）。
 * ⚠️ 准备期它是"按钮里的第一行"、灾害期它是普通文字 —— **两个状态共用同一块位置**，
 *    所以必须从 `SKIP_BTN` 推出来（各写一个数必然漂：动一个漏一个）。
 */
export function skipTextInsetX() { return (SKIP_BTN.x - HUD.pad) + 10; }
/**
 * ⚠️ 2026-10-05：按钮左缘从"面板内 130"挪到 **185**，就是为了左边那一栏能塞下
 *    「整备中 · 不计时」（冻结期的状态字，bold 22，实测宽 **154.8px**）。
 *    原来 130 起时，那行字会**压进按钮里**（用户报的"状态面板有些重叠"）；
 *    而 130 → 185 之后按钮宽 229，里面最长那行「▶ 提前开波（离开庇护所后可用）」实测 **197.1px**，
 *    仍然放得下（左内边距 10 + 197 + 右 22）✓。
 */

/**
 * "提前开波"按钮矩形。
 * ⚠️ 它**必须跟着状态面板走**（2026-10-05 修）：原来返回的是一个**写死的常量矩形**
 *    （`HUD.pad + 130` 这种），而状态面板从这一轮起可以拖动 ⇒ 一拖面板，
 *    按钮就留在原地（**面板走了、按钮和它的命中区还钉在原处**）。
 *    ⚠️ 同一个病在本轮出现三次：属性面板本体、仓库格子/分区标题、还有这个按钮 ——
 *    全都是"子矩形按**基准常量**算，没走面板的 offset rect"。
 * ⚠️ 收起时返回**空矩形**（`pointInRect` 对空矩形恒 false）：收起态根本不画这个按钮，
 *    命中判定也必须一起失效（同 `bagSlotRect` / `storageSlotRect`）。
 */
export function skipBtnRect() {
  if (UI_LAYOUT.hud.collapsed) return { x: 0, y: 0, w: 0, h: 0 };
  const p = hudPanelOpenRect();
  return { x: p.x + (SKIP_BTN.x - HUD.pad), y: p.y + (SKIP_BTN.y - HUD.pad), w: SKIP_BTN.w, h: SKIP_BTN.h };
}

export const PLAYER = {
  speedBase: 150,
  speedPerWeight: 0.025,
  speedMin: 55,
  maxHp: 100,
  digRadius: 52,           // 站在材料点多近可以挖（水平距离）
  // 竖直方向多近才算"站在这一堆旁边"（2026-09-27 加，见 world.js 的 atSpot）。
  // ⚠️ 为什么需要它：桥上的废墟和它**正下方**的地面废墟，x 可能只差几十 px，
  //    只比 x 会把两者混为一谈 → 桥上挖出来的材料永远收不走（用户报的 bug）。
  // 取值 40 的依据：同一层地面差 **14**（料堆站在地形上 14px）、
  //    而隔壁桥面至少差 **78-14 = 64**（岩桥自检保证"离地 ≥78px"）→ 40 落在两者中间，
  //    顺带还能容忍一级台阶（`stepUp` 26）。
  digVertTol: 40,
  buildRadius: 150,        // 离庇护所多近可以往墙上贴材料
};

// 撑过一波后主角回血（2026-09-26 用户决定："每波恢复固定量"，不回满）。
//
// ⚠️ 为什么必须有这条：12 波共用 100 血在数学上不可能通关 ——
//    实测最好的装配全 12 波要吃 2896 点伤害（100 血的 29 倍）。
//    有回血之后，"每一波"才成为一个可独立通过的考试。
//
// ⚠️ 为什么是"固定量"而不是"回满"：回满会让"上一波打得好不好"完全不带到下一波，
//    血量就退化成装饰；固定量保留了"连续打差会崩盘"的张力。
//    当前值 45 < 满血 100，所以 100 血大约能连续吃 2 波硬仗。
export const PLAYER_HEAL_PER_WAVE = 45;

/** 撑过一波后回血。放在 config 里是为了让 tools/simulate.js 和游戏用同一条规则 */
export function healAfterWave(hp) {
  return Math.min(PLAYER.maxHp, hp + PLAYER_HEAL_PER_WAVE);
}

