  halfWidth: 160,
  wallThickness: 40,
  rise: 140,
  heightMin: 100,          // 全屋结构材料平均龙级时的有效高度
  heightMax: 200,          // 虫级或未安装结构材料时的有效高度
  // 庇护所的范围半径（= 庇护所自身的 footprint，所以画出来的边界和判定边界一致）。
  // ⚠️ 2026-09-26 取消"安全区"之后**它不再是安全区**（原名 safeRadius，已改名）：
