  //    留这个半径只为"判定你在不在庇护所范围内"，不再有任何免伤含义。
  shelterRange: 160,
  // ⚠️ 2026-09-29：**料堆离庇护所中心的最近距离**（世界生成时过滤，见 world.js 的 onWaveStart）。
  //    背景：准备期改成"从人物离开庇护所才开始计时"（用户 2026-09-29 要求），
  //    于是冒出一个新漏洞 —— 料堆若生成在近处，玩家**站在庇护所范围里就能挖到它**
  //    （挖掘半径 52）→ 等于"不出门白拿料、倒计时永远不启动"。
  //    实测（300 张地面图 / 14743 个料堆）：**岩桥上的料堆最内能到 125px**，
  //    低于门槛的有 17 个（约 1/18 的波次）→ 必须挡。
  // ⚠️ 取值 240 = `shelterRange(160) + PLAYER.digRadius(52) + 余量(28)`：
  //    玩家站在 160 的边界上，离最近的料堆仍有 **80px > 52** → 够不着 ✓
  // ⚠️ 为什么不直接把 `shelterRange` 改小：那个值同时是"画出来的边界线"和"灾害的判定范围"，
  //    改它会连带改玩法；生成侧过滤只影响"料堆长在哪"，代价最小。
  // ⚠️ 兜底：`main.js` 里还有一条"**挖到任何料就立刻算已出门**"——
