// 规则（用户定）：
//   · 结构材料**两两有序合成** → 高一级。配方表在文件末尾的 `SYNTH_RECIPES`
//     （**有序**，所以 [A,B] 和 [B,A] 是两条不同的配方）
//   · 失败有两种结果：**降级**（出"次X级"）或**彻底报废**（不可逆损失）
//   · **材料级别越高，成功率越低**（用户明确要求）
//   · 功能材料（道具）和修复材料**不能合成**
//   · 次蛇级 / 次蛟级 / 次龙级**只能靠合成失败拿到**，废墟里挖不到（见 ZONES 的注释）
//
// ⚠️ 骨架期材料表是"每级 2 种取向"（见 MATERIALS 上面的注释），所以配方只有 8 条；
//    完整设计的 57 条（36 + 18 + 3）要等材料表补到 125 种。配方写成**显式表**而不是
//    按 id 规则推算 —— 这样"哪些组合有效"是可读、可审、可自检的。
//
// ⚠️ 交互形式（用户 2026-09-27 选定）：**庇护所工作台 + 后台 30 秒倒计时** ——
//    必须走到工作台启动，启动后可以自由行动（文档 7.2 的设计被用户点名保留），
//    并叠加文档 7.3 的两条风险：合成中**工作台受损 → 进度暂停**（不清零）、
//    **工作台被打穿 → 投入的材料损失**。
//    ⚠️ 骨架期"工作台受损/被打穿"的判定挂在**庇护所的任意一面**上：
//       有面被打穿 = 暂停；已经破着的面又被打 = 投入材料损失（见 main.js 的事件循环）。
//       这样不用给工作台单独造一套血量，语义也说得通（"房子漏了，台子上的活干不下去"）。
//       将来若要精细到"工作台自己那一面"，再加字段即可。
export const SYNTH = {
  seconds: 30,                                  // 📊 后台倒计时（文档 7.2 的 30 秒）
  // 📊 成功率随投入材料的档次**递减**（用户要求"材料级别越高，成功率越低"）。
  //    键 = 投入材料的 tier（1 虫级 / 3 蛇级 / 5 蛟级）—— 次X级不能投入合成。
  // ⚠️ 查不到的档位会**静默失效**（乘 undefined = NaN）→ 已在配方自检里断言必须声明全。
  successRate: { 1: 0.85, 3: 0.65, 5: 0.45 },
  // 📊 失败时"彻底报废"占的比例（其余降级为"次X级"）。同样随档次升高而更狠。
  scrapShare:  { 1: 0.15, 3: 0.30, 5: 0.50 },
  // ---------- 取货展示的时长（2026-09-29 加）----------
  // 背景（用户要求）：合成产物**不再直接落袋**，先暂存在工作台上；玩家点工作台 → 对材料
  //   有一个"特写展示" → 然后才自动放进背包/仓库（放不下就留在台子上并提醒）。
  // ⚠️ 这个值只管**展示段**的时长（材料从台子上浮、飞向仓库那一小段）。
  //    ⚠️ 千万别把它做成"全屏过场"：这个项目是 2D canvas、没有摄像机，而且**游戏不暂停** ——
  //       灾害期合成完成时如果遮住画面，玩家会看不见自己正在挨打（用户 2026-09-29 明确选了
  //       "只做小提示，不遮屏"）。
  takeSeconds: 0.9,
};

/**
 * 工作台在世界里的位置（**庇护所内部**，左右并排）。几何只在这里定义一次，render 与 main 共用。
 *
 * ⚠️ 2026-09-27 用户要求"把工作台放进庇护所" + "第 5 波后再增加一个工作台"：
 *    从"庇护所右侧的屋外"搬进**内墙之间**（内区 x 2280~2520、y 370~570，即 240×200）。
 *    两个台子 96 宽 + 间隔 24 = 216 ≤ 240 ✓。`offs` 是"左上角 x − 庇护所中心"。
 *    · 台子直接坐在地上（底边 = groundY），所以 `drawWorkbench` 的腿高会算成 0（不再需要腿）。
 *    · 搬进来之后**不会再和料堆抢点击**：近区废墟最近也在庇护所外 180px 处，
 *      原先"抬到 groundY-140 避开料堆命中区"的理由（见 docs/04）已经不存在了。
 *    · ⚠️ 但**不能碰到墙面矩形**（左墙 2240~2280 / 右墙 2520~2560）：`main.js` 里
 *      工作台的命中判定排在墙面**之前**，一旦重叠就会出现"想点墙却打开了合成面板"。
 *      现在的 2292~2388 / 2412~2508 两侧各留 12px ✓。
 *
 * ⚠️ 2026-10-02：`h` 从 64 改成 **41** —— 工作台换成像素画贴图后，素材的宽高比是 **2.33 : 1**
 *    （96 宽 → 41 高）。留 64 的话台子只占框的下半部、上面空 23px，而那圈**状态描边**
 *    （`render.js` 里按 `busy` / `near` 画的那个框）是按 `w × h` 画的 → 描边会明显比台子高
 *    一截、箍不住它（验收截图里一眼可见）。
 *    · 牵连面只有三处，都已核对：绘制、`main.js` 的点击命中（`pointInRect(workbenchRect(i))`）、
 *      取货特效的锚点（`fxGather(br.x + br.w / 2, br.y)`）—— 全都"跟着矩形走"，改 h 自洽。
 *    · 台面上产物的位置是 `r.y + r.h - 40` → 改后落在 41−40 = 台面顶部附近，仍在台面上 ✓。
 *    ⚠️ 贴图是用 `--inset 2` 出的（框箍紧后覆盖率会到 90%+ 撞断言），所以台子四周有 2px 余量。
 *
 * ⚠️ 2026-10-05：`h` 41 → **47** —— 工作台**重做成"合成台"造型**（用户要求：从"木台 + 工具"
 *    换成一台合成装置），新素材的宽高比是 **2.03 : 1**（96 宽 → 47 高）。
 *    理由和上面那次**完全一样**：**框与素材比例错位时改的是框，不是素材** ——
 *    留 41 的话素材只占 75 宽、左右各空 10px，那圈状态描边又箍不住它了（验收截图一眼可见）。
 *    · 三个消费者仍然全部"跟着矩形走"（绘制 / 点击命中 / 取货锚点），改 h 自洽 ✓
 *    · ⚠️ 这一次**不用 `--inset`**：新素材的剪影更"开"（覆盖率 72%，低于 90% 那条线）；
 *      硬加 `--inset 2` 反而会把可用框变成 92×43（比例 2.14）→ 和素材再错位一次。
 *    · 改完必须重跑"**框箍不箍得住**"的截图验收（这条正是 2026-10-02 那次踩出来的）。
 */
export const WORKBENCH = { w: 96, h: 47, offs: [-108, 12] };

/** 第 i 号工作台的矩形（i 越界时退回最后一个，免得少一个台子就整个消失） */
export function workbenchRect(i = 0) {
  const off = WORKBENCH.offs[Math.min(i, WORKBENCH.offs.length - 1)];
  return {
    x: SHELTER.cx + off,
    y: WORLD.groundY - WORKBENCH.h,
    w: WORKBENCH.w,
    h: WORKBENCH.h,
  };
}

/** 位置表里有几个台子（= 最多同时能放几个） */
export function workbenchCapacity() { return WORKBENCH.offs.length; }

// 合成面板（**屏幕坐标**，和仓库面板同类）—— 打开后从背包 + 仓库里挑两件结构材料。
// ⚠️ 几何同样只定义一次：render 负责画、main 负责命中判定，两边各写一套坐标必然漂移
//    （HUD 的"提前开波"按键提示漂掉就是这么来的，见 docs/04）。
export const SYNTH_PANEL = {
  fitted: false, x: 0, y: 0, w: 0, h: 0,
};
// Drawing and pointer hits share the same pixel-sized assembly rail and material grid.
export function synthGeometry() {
  const height = typeof document !== 'undefined' ? document.getElementById('game')?.getBoundingClientRect().height : VIEW.h;
  const u = VIEW.h / (height || VIEW.h), pw = Math.min(760 * u, VIEW.w - 24 * u), ph = Math.min(420 * u, VIEW.h - 24 * u);
  const panel = SYNTH_PANEL.fitted ? { x: SYNTH_PANEL.x, y: SYNTH_PANEL.y, w: SYNTH_PANEL.w, h: SYNTH_PANEL.h }
    : { x: (VIEW.w - pw) / 2, y: (VIEW.h - ph) / 2, w: pw, h: ph };
  const pad = 12 * u, sideW = (panel.w < 560 * u ? 136 : 180) * u, gap = 8 * u, cellH = 80 * u;
  const optionX = panel.x + pad + sideW + 16 * u, gridW = panel.x + panel.w - pad - optionX - 44 * u;
  const columns = Math.max(1, Math.floor((gridW + gap) / (64 * u + gap)));
  const top = panel.y + 58 * u, bottom = panel.y + panel.h - 58 * u;
  const rows = Math.max(1, Math.floor((bottom - top - 24 * u + gap) / (cellH + gap)));
  return { panel, u, pad, sideW, gap, cellH, optionX, gridW, columns, rows, top, bottom, cellW: (gridW - (columns - 1) * gap) / columns };
}
export function synthPanelRect() {
  return synthGeometry().panel;
}
/** 两个投入槽（i = 0 / 1） */
export function synthSlotRect(i) {
  const g = synthGeometry(), slot = (g.sideW / g.u < 150 ? 56 : 68) * g.u;
  return {
    x: g.panel.x + g.pad + i * (slot + 20 * g.u), y: g.top + 24 * g.u, w: slot, h: slot,
  };
}
/**
 * 候选材料格。
 * 绘制和命中共用同一滚动偏移，超出窗口的部分不可点击。
 */
export function synthOptionRect(i, scrollY = 0) {
  const g = synthGeometry(), col = i % g.columns, row = Math.floor(i / g.columns);
  return {
    x: g.optionX + col * (g.cellW + g.gap), y: g.top + 24 * g.u + row * (g.cellH + g.gap) - scrollY, w: g.cellW, h: g.cellH,
  };
}
export function synthOptionCapacity() {
  const g = synthGeometry(); return g.columns * g.rows;
}
export function synthScrollGeometry(count, scrollY = 0) {
  const g = synthGeometry(), view = { x: g.optionX, y: g.top + 24 * g.u, w: g.gridW, h: g.bottom - g.top - 24 * g.u };
  const contentH = Math.max(0, Math.ceil(count / g.columns) * (g.cellH + g.gap) - g.gap);
  const max = Math.max(0, contentH - view.h), offset = Math.max(0, Math.min(scrollY, max));
  const rail = { x: view.x + view.w + 4 * g.u, y: view.y, w: 40 * g.u, h: view.h };
  const thumbH = Math.min(view.h, Math.max(44 * g.u, view.h * view.h / Math.max(view.h, contentH)));
  const thumb = { x: rail.x + 10 * g.u, y: rail.y + (max ? offset / max : 0) * (rail.h - thumbH), w: 20 * g.u, h: thumbH };
  return { view, rail, thumb, max, offset };
}
export function synthStartRect() {
  const g = synthGeometry(), w = Math.min(176 * g.u, g.panel.w - g.pad * 2 - 112 * g.u);
  return { x: g.panel.x + g.panel.w - g.pad - w, y: g.bottom + 8 * g.u, w, h: 44 * g.u };
}
export function synthCloseRect() {
  const g = synthGeometry(); return { x: g.panel.x + g.panel.w - g.pad - 44 * g.u, y: g.panel.y + 8 * g.u, w: 44 * g.u, h: 44 * g.u };
}

// 长按修复（2026-09-25 用户要求）：
//   · 按住墙面超过 holdSeconds 才算"长按修复"，短按仍是"拆下材料"
//   · **消耗修复材料**（不再免费），而且**越稀有的材料越贵、越慢**
//   · 只在"还没彻底破损"（耐久 > 0）时才修得回来；归零消失了只能换新料
export const REPAIR = {
  holdSeconds: 0.35,
  // ⚠️ 2026-09-26：材料从 2 档扩到 7 档，两张表也要跟着铺满 7 档。
  //    规则不变：**越稀有越贵、越慢**（每秒恢复更少、每点耐久的修复量更贵）。
  perSec:     { 1: 14, 2: 11, 3: 9,   4: 7,   5: 6,   6: 5,   7: 4    },
  unitsPerHp: { 1: 1,  2: 1.5, 3: 2,  4: 3,   5: 4,   6: 5,   7: 6    },
};

// 庇护所仓库（2026-09-25 用户要求）：只在庇护所范围内才显示/可交互
// ⚠️ 二次调整：容量 12 → 24，并且**按三个类别分区存放**
//   （修复材料 8 格 / 结构件 8 格 / 功能件 8 格）
//   分区是硬约束 —— 修复材料放不进结构件的格子。
// ⚠️ 2026-09-27 第三次调整（用户要求"扩容仓库"）：每区 8 → **10**（列 4 → 5），共 **30 格**。
//    为什么只加列不加行：面板高度已经顶到帮助文案那一带（y 168~558），再加一行会盖住底部文案；
//    而宽度 214 → 264 后是 1000~1264，离屏幕右缘还剩 16px，够用。
export const STORAGE = {
  sections: ['repair', 'struct', 'func'],   // 分区顺序（从上到下）
  cols: 5,
  rows: 2,
  perSection: 10,
  x: 1000,
  y: 168,
  slot: 44,
  gap: 6,
  pad: 10,
  titleH: 24,
  sectionH: 16,
  sectionGap: 8,
};

export const STORE_PER_SECTION = STORAGE.cols * STORAGE.rows;              // 每区 10 格
export const STORE_SLOTS = STORE_PER_SECTION * STORAGE.sections.length;    // 共 30 格

/**
 * 仓库面板的**基准矩形**（不含拖动偏移、不含收起）—— 面板几何只算这一份。
 * ⚠️ 单独抽出来是因为：`storagePanelRect()` 收起时会返回标签，标签不能拿去算格子/分区标题。
 */
function storageBaseRect() {
  const w = STORAGE.pad * 2 + STORAGE.cols * STORAGE.slot + (STORAGE.cols - 1) * STORAGE.gap;
  const rowsH = STORAGE.rows * STORAGE.slot + (STORAGE.rows - 1) * STORAGE.gap;
  const secH = STORAGE.sectionH + rowsH + STORAGE.sectionGap;
  const n = STORAGE.sections.length;
  const h = STORAGE.titleH + STORAGE.pad + n * secH - STORAGE.sectionGap + STORAGE.pad;
  return { x: STORAGE.x, y: STORAGE.y, w, h };
}

/** 仓库面板"展开 + 套拖动偏移"矩形 */
function storagePanelOpenRect() { return uiOffsetRect(storageBaseRect(), 'storage'); }

/** 仓库面板矩形：收起时直接返回标签矩形（见 UI_LAYOUT / UI_CHROME）。
 *  ⚠️ 不影响下面的 `storageSlotRect` —— 它单独用 `storageBaseRect()` 起算，收起时直接返回空矩形。 */
export function storagePanelRect() {
  return UI_LAYOUT.storage.collapsed ? uiLabelRect('storage') : storagePanelOpenRect();
}

/**
 * 分区内第 k 格的左上角。
 * ⚠️ 原点必须取 `storagePanelOpenRect()`（**含拖动偏移**），不能取 `STORAGE.x/y` 基准常量 ——
 *    2026-10-05 的 bug 就是这么来的：仓库面板变成可拖之后，**底板走了、30 个格子和分区标题
 *    还留在基准位置**（画面上表现为"格子散在别处"，而且命中判定也跟着错）。
 */
function sectionSlotPos(sec, k) {
  const col = k % STORAGE.cols;
  const row = Math.floor(k / STORAGE.cols);
  const rowsH = STORAGE.rows * STORAGE.slot + (STORAGE.rows - 1) * STORAGE.gap;
  const secH = STORAGE.sectionH + rowsH + STORAGE.sectionGap;
  const p = storagePanelOpenRect();
  return {
    x: p.x + STORAGE.pad + col * (STORAGE.slot + STORAGE.gap),
    y: p.y + STORAGE.titleH + STORAGE.pad + sec * secH
       + STORAGE.sectionH + row * (STORAGE.slot + STORAGE.gap),
  };
}

/**
 * 平铺索引 0..23 → 格子矩形（分区顺序：修复材料 → 结构件 → 功能件）。
 * ⚠️ 收起时返回**空矩形**：空矩形 `pointInRect` 恒 false，于是"收起的仓库格子点不到"
 *    这条自动成立（背包格 / 拖材料落点判定都不用单独去改 main.js）。
 * ⚠️ 2026-10-05：仓库**已经可以拖动**了（原注释写的"仓库不可拖，dx/dy 恒 0"已作废）——
 *    位置改由 `sectionSlotPos` 从 `storagePanelOpenRect()` 起算。
 */
export function storageSlotRect(i) {
  if (UI_LAYOUT.storage.collapsed) return { x: 0, y: 0, w: 0, h: 0 };
  const sec = Math.floor(i / STORE_PER_SECTION);
  const k = i % STORE_PER_SECTION;
  const p = sectionSlotPos(sec, k);
  return { x: p.x, y: p.y, w: STORAGE.slot, h: STORAGE.slot };
}

/** 分区标题的基线位置（⚠️ 同样要跟着面板的拖动偏移走，见 `sectionSlotPos`） */
export function storageSectionLabelPos(sec) {
  return {
    x: storagePanelOpenRect().x + STORAGE.pad,
    y: sectionSlotPos(sec, 0).y - 5,
  };
}

// ---------- 挖掘：多点几下越稀有 ----------
// 每次点击深入一层并产出一块材料，先进"脚下暂存堆"；塌方则暂存全丢。
// 于是"多点几下"是一个干净的贪/稳赌博：越深越值钱，但一次塌方全没。
export const DIG = {
  tapSeconds: 1.0,        // 每次点击的挖掘耗时（这段时间主角不能移动、不能连点）

  // ⚠️⚠️ 2026-09-27 第六轮改（用户定案）：**废墟能挖多深，按"类型"分开定**。
  //     用户原话："改为只有稳定性可以挖 1 到 2 块，其他的可以挖多层，
  //               但是除了引怪性外，只能挖一次，挖完就消失"。
  //     澄清后确认：① 引怪型挖到底**不消失**、可以反复挖（代价是每次都引怪）；
  //                ② 易塌/引怪用回原来的 **4~9 层**。
  //
  //     为什么这么改（回看第五轮的实测）：把**所有**废墟都压成 1~3 层之后，
  //     全图产出 -71%、龙级 -52%，而且"按层索引的掉落表"每区只够得到前 3 张
  //     → **中区塌得和近区一样**（平均档 1.88 → 1.41）、蛟级占比 16% → 2.9%。
  //     改成"只有稳固型是短的"，多层那两类就能重新吃到后 3 张表，梯度回来了。
  //
  //     于是三种废墟现在是三条完全不同的曲线（这才是"类型"该有的分量）：
  //       · **稳固**（稳）1~2 块 · 挖完**消失** → 安全小产出，一次性
  //       · **易塌**（塌）4~9 层 · 挖完**消失** → 深挖高风险高回报，一次性
  //       · **引怪**（怪）4~9 层 · 挖完**不消失** → 唯一可反复挖的（用"每次引怪"换持续产出）
  //
  //     ⚠️ 这张权重表是**唯一**的产出分布定义（`rollDepth` 直接读它，别在别处写死区间）。
  //        key = `RUIN_TYPES` 的 id，配一道启动自检（见下），漏一个类型会在加载时抛错。
  //     ⚠️ 4~9 层那两档写的是"每层等权"（全是 1）—— 想改成"越浅越常见"直接改数字即可。
  depthWeights: {
    stable: { 1: 50, 2: 50 },
    caveIn: { 4: 1, 5: 1, 6: 1, 7: 1, 8: 1, 9: 1 },
    lure:   { 4: 1, 5: 1, 6: 1, 7: 1, 8: 1, 9: 1 },
  },

  caveInPerDepth: 0.09,   // 每深入一层，塌方概率 +9%
};

/**
 * 抽一个废墟的层数（= 它一共能产出几件材料）。
 * @param {function} rng
 * @param {string} type `RUIN_TYPES` 的 id（stable / caveIn / lure）—— 三种类型的层数范围不同
 * ⚠️ 权重**只从 `DIG.depthWeights` 读**，不在这里写死阈值 —— 要改产出分布只改那一处。
 */
export function rollDepth(rng, type) {
  const w = DIG.depthWeights[type];
  const keys = Object.keys(w);
  let total = 0;
  for (const k of keys) total += w[k];
  let r = rng() * total;
  for (const k of keys) { r -= w[k]; if (r < 0) return Number(k); }
  return Number(keys[keys.length - 1]);
}

// ⚠️ `DIG.depthWeights` 的自检放在 `RUIN_TYPES` 定义**之后**（它要遍历类型 id）—— 见下面。


// ---------- 废墟的三种类型（2026-09-25 用户要求）----------
// "一种不会塌也不吸引怪兽，一种会吸引怪兽但不塌，一种会塌但不吸引怪兽"
// ⚠️ 类型必须对玩家可见 —— 看不到类型就没法做选择，这个系统就等于不存在。
//
// ⚠️⚠️ 2026-09-27 第六轮（用户定案）：**三种类型现在连"能挖多深 / 挖完消不消失"都不同**。
//    `refill` = 挖到底之后**不消失**、还能再挖一轮。只有引怪型是 true。
//    用户原话："除了引怪性外，只能挖一次，挖完就消失"
//    （澄清：1 轮 = 从第 1 层挖到底；"消失"指废墟从地图上移除，原来的"走开自动收走"不变）。
//    层数范围见 `DIG.depthWeights`（稳固 1~2 / 易塌、引怪 4~9）。
// ⚠️ 2026-10-05：每种类型下面的 `color` **暂时没有消费者**了 —— 头顶那个"写类型名的药丸标签"被删掉
//    （用户："不要用文字表明，不同的图表示不同的废墟"），类型现在由三张**外形不同**的图表达
//    （映射见 `render.js` 的 `RUIN_TEX_KEY`）。色号留着是因为它记着一条真实修正
//    （"稳固"原来那支冷灰蓝 `#7f8b9c` 是这一组里唯一的冷色孤儿），也备将来做图例/小地图标记时复用 ——
//    ⚠️ 复用前先确认它和画面里那张图**不打架**（红/橙色已经分别被"引怪/易塌"的图占住了）。
export const RUIN_TYPES = {
  stable: {
    id: 'stable', name: '稳固', short: '稳',
    caveIn: false, lure: false,
    refill: false,          // 挖完就消失（1~2 块，安全但一次性）
    // ⚠️ 2026-10-01：`稳固` 原来是冷灰蓝 `#7f8b9c` —— 它是这一组里唯一的孤儿：
    //    另外两档（引怪 / 易塌）用的值**恰好就是** `UI_SKIN.danger` / `UI_SKIN.warn`，
    //    说明这一组本来就是"语义色"，只是 `稳固` 那份没跟上。改成暖灰（= textMid），
    //    "中性灰＝安全"的意思不变，但它不再在暖棕世界里当唯一的冷色。
    color: UI_SKIN.textMid,
    desc: '不会塌、不引怪 · 只有 1~2 块，挖完消失',
  },
  lure: {
    id: 'lure', name: '引怪', short: '怪',
    caveIn: false, lure: true,
    refill: true,           // ⚠️ 唯一可反复挖的：挖完还在，能再来一轮（代价是每次挖都引怪）
    color: UI_SKIN.danger,
    desc: '挖掘会招来怪物 · 4~9 层，挖完不消失、可反复挖',
  },
  caveIn: {
    id: 'caveIn', name: '易塌', short: '塌',
    caveIn: true, lure: false,
    refill: false,          // 挖完就消失（4~9 层，深挖高风险高回报，一次性）
    color: UI_SKIN.warn,
    desc: '越挖越容易塌 · 4~9 层，挖完消失',
  },
};

// 启动自检：每个废墟类型都要有自己的产出权重表，且层数 ≥1、权重 >0。
// ⚠️ 为什么必须有：漏一个类型 → `rollDepth` 里 `Object.keys(undefined)` 抛错（或者写了兜底之后
//    静默返回 NaN → `depth >= maxDepth` 永远为假 → **废墟永远挖不到底**）；空表同样返回 NaN。
//    两条都属于"不报错的坏"，和"开关类字段默认成 0"是同一类坑。
{
  const bad = [];
  for (const t of Object.keys(RUIN_TYPES)) {
    const w = DIG.depthWeights[t];
    if (!w) { bad.push(`${t} 没有 depthWeights 条目`); continue; }
    const ws = Object.entries(w);
    if (!ws.length || ws.some(([k, v]) => !(Number(k) >= 1) || !(v > 0))) bad.push(`${t} 的权重写坏了`);
  }
  if (bad.length) throw new Error('DIG.depthWeights 写坏了（会让废墟永远挖不到底）：\n  ' + bad.join('\n  '));
}

// 引怪机制：挖"引怪型"废墟时发出声响，把附近的怪物拉过来
export const LURE = {
  radius: 320,       // 声响能传多远
  seconds: 3.0,      // 被打扰的怪物朝声源走这么久，之后回去巡逻
  speedMult: 1.35,   // 被吸引时的速度倍率（74×1.35≈100，仍慢于主角的 150，所以跑得掉）
};

// 掉落类别比例：**固定 52% / 35% / 13%**（2026-09-29 用户："把功能材料的获得率调高一点点"）
// 深度不再改变类别比例，只决定"类别内部选哪个具体材料"（越深越偏进阶件）。
// 这样"修复材料最多"这条一定成立，不会像之前那样出现贴边被采样噪声翻掉的情况。
//
// 历史（别删，决策痕迹）：
//   · 2026-09-26 第二次调整：50/30/20 → **55/35/10**。
//     方向是"修复和结构各多一点，功能砍一半"—— 理由：功能件只有 8 种道具、且**每种只管一个灾害**，
//     本来就最容易堆着没用；而修复/结构是每波都要消耗的（修裂痕、补打掉的结构件）。
//   · 2026-09-29 回调一点点：55/35/10 → **52/35/13**（用户要求）。
//     ⚠️ 这 3 个点**全部从"修复"扣**，**不动"结构"** —— 因为结构件的收入结构是难度标定的基线
//     （★顶配装配全靠它），动它会连带改难度；修复是三个里最大的池子，扣 3 个点影响最小。
//     📊 实测（20 局 × 12 波 × 两层挖穿，真实 `digOnce`；总件数两次都是 66496，即总量没变）：
//        改动前 结构 36.37%（100.8 件/波·两层）· 修复 54.03%（149.7）· 功能 9.59%（26.6）
//        改动后 结构 36.40%（100.9）        · 修复 51.06%（141.5）· 功能 12.54%（34.8）
//        → 功能件一整局（12 波）从 **319 件 → 417 件**（+31%）；结构件几乎没动（100.8 → 100.9）。
//     ⚠️ 结构那 0.03 个点的漂移不是"改了结构的权重"（没动），而是**权重变了之后同一个随机数
//        落进了不同的累积区间** —— 类别靠 `pickWeighted` 的区间划分决定，边界一动就有极少数件换类别。
//        本项目记过同一族的坑（"分布等价 ≠ 同种子逐件等价"），所以验收要看**分布**、不是逐件比对。
//     ⚠️ 实测到的比例与权重不完全相等（结构 36.40% > 35）：因为**龙级废墟那条路径绕过了类别抽签**
//        （`digOnce` 里 t7 判定在类别抽之前就 return 了），那部分算进结构件。
//     ⚠️ 功能件的档位是**按深度给**的，不是这个权重管的：
//        t1 43% / t2 27% / t3 30%；分区看 **近区只有 t1、中区 t1+t2、深区全档、极深区几乎全 t3**。
//        所以要"更容易凑齐某个灾害的道具"得看深度分布，光抬权重只是等比例放大。
export const LOOT_CATEGORY_WEIGHTS = { repair: 52, struct: 35, func: 13 };

// 探索区域：距离越远 → 材料越好、风险越高
//   tables[i] = 第 (i+1) 层的"类别内候选表"（每个类别内部的权重）
//   类别由 LOOT_CATEGORY_WEIGHTS 按 52/35/13 抽，抽完再看这张表定具体材料
// ⚠️ 材料点外观必须完全一样，不能靠颜色区分，否则"随机挖出"就没意义了
// ⚠️⚠️ 掉落表里的每个 id 都必须真实存在于 MATERIALS —— 改材料表时必须同步改这里！
//    等级梯度：近区 虫级 → 中区 虫级+蛇级 → 深区 蛇级+蛟级，**龙级只在深区最深层**（"危险的废墟"）。
//    ⚠️ 次蛇级(2)/次蛟级(4)/次龙级(6) **永远不会掉出来** —— 它们只能靠"合成失败"得到（用户要求）。
//
// ⚠️⚠️ 2026-09-28（材料表扩容到 125 种）之后，这张表有**三条硬规则**：
//    ① **只有"纯取向"料能被挖到**：混合料（`t3_hard_soft` 这种、共 60 个）是**合成专属**的，
//       永远不出现在这里。这与文档 5.0 的"来源"列一致（虫级=废墟、蛇级/蛟级=合成成功）。
//    ② 每个档**实际存在的纯取向个数不一样**，拆权重时不能一律按 6 个分：
//       t1 六种 / t3 六种 / **t5 只有 3 个**（板·膜·砖 —— 只有 3 条灾害线的代表取向能当纯料）/ t7 两种（板·膜）。
//       镜/匣/翼 在 t7 走的是 `T7_RUIN.pool` 那条独立判定（"龙级废墟"），不靠普通表。
//    ③ **每层的"档位总权重"和扩容前完全一致**（扩容前是 14 种、现在是 125 种，但每一层的
//       各档权重之和没动，只是把一个档位的权重摊到了多个取向上）。所以"材料收入结构"没变，
//       只是"同样能挖到 3 份蛇级，但可能是板/膜/镜/匣里的任意几种" —— 难度口径不动。
//       摊法 = 按该档可用取向**依次轮发**，且**每个深度带从"它这一档新解锁的取向"起头**：
//         层 1~2 从 板 起（只有 板/膜）→ 层 3~4 从 镜 起（板/膜/镜/匣）→ 层 5~6 从 翼 起（全 6 个）。
//         某层"蛇级 3 份" = 镜+匣+板（不是 板+膜+镜）。
//       ⚠️ 那个"起头位置"不是装饰，是**必需**的：不加它，层 1~2 永远只发板/膜，
//          而层 5~6 的虫级权重最多 4 份 → 轮发永远轮不到第 5、6 个取向 →
//          **t1_light / t1_tough 一次都挖不到**；而虫级没有更低的料能合成出来，
//          这两种就成了"永远拿不到的死内容"（200 波冒烟实测抓到的）。
//       ⚠️ 所以"越深的层越能见到稀有取向"这条梯度是**由起头位置给的**，改它等于改产出分布。
//
// ⚠️ 2026-09-28（同一天、补道具第 3 档）：**func 段的档位也随深度推进**，规则是
//     近区 / 中区浅层 = **虫档**（rod1…）→ 中区第 4 层 ~ 深区第 4 层 = **蛇档**（rod2…）→
//     深区第 5、6 层 ~ 极深区 = **蛟档**（rod3…）。
//     每层保持**条目数与"覆盖的灾害种类"不变**（即"换档"而不是"叠加"），
//     所以这一改动**没有净增道具供给**，只是让"中盘挖到的是中盘该用的档"。
/**
 * 第 i 个区（0 起）在左右两侧的**绝对 x 区间**。
 * ⚠️ 由 `WORLD.zoneEdges`（相对庇护所的距离）推导 —— 改世界宽度、加区、缩区时
 *    **不用手算坐标**。前两轮都是写死的绝对坐标，每次改宽度要手算十几个数字、还漏改过（见 docs/04）。
 */
export function zoneRanges(i) {
  const cx = SHELTER.cx;
  const a = WORLD.zoneEdges[i];
  const b = WORLD.zoneEdges[i + 1];
  return [[cx - b, cx - a], [cx + a, cx + b]];
}

