//    改成 **6:3:1 / 3:2:1 / 2:3:2 / 2:3:3**（近区不动 —— 它本来就是最安全的一区）。
//    实测（300 波 × 两层，走真实生成逻辑）：全局 **稳固 27.3% → 37.0%、引怪 37.0% → 24.4%**，
//    各区引怪变成 **14.6 / 17.5 / 28.2 / 35.8%** —— **"越远越多引怪"的梯度保留**（深区、极深区仍明显高于近区）。
//    ⚠️ 连带代价（本轮**没有补偿**）：引怪型是三种里**唯一挖完不消失、可反复挖**的，
//      也就是"可持续产出"的唯一来源（实测 **83% 的龙级来自引怪型**）。
//      每波可反复挖的引怪型 **16.5 → 10.9 个**（两层平均；地面单独看是 17.8 → 11.7）→ 材料与龙级的
//      **长期收入会跟着降**，这不只是"危险变少"。将来觉得收入不够，**补偿手段是抬 `T7_RUIN.rate`，别把引怪比例加回来**。
