// ============================================================
// 启动自检：配方表
// ============================================================
// ⚠️ 为什么必须有（和掉落表自检同源，见上面那条"掉落表引用了不存在的 id"）：
//    配方里的 id 一旦写错，症状不是"报错"，而是 `MATERIALS[id]` 为 undefined →
//    合成完成那一刻读 `.name` / `.color` 抛异常 → **主循环整个死掉、画面冻住**，
//    而玩家看到的只是"合成到一半就卡住了"。所以让它在加载时直接炸。
// ⚠️ 同时断言"每个可合成档位都在 SYNTH.successRate / scrapShare 里声明过" ——
//    查不到的档位会变成 `rng() < undefined` = false，即**成功率静默成 0**（永远失败），
//    这属于本项目最怕的"机制静默失效"（见 docs/04）。
{
  const bad = [];
  const seen = new Set();
  for (const r of SYNTH_RECIPES) {
    const ma = MATERIALS[r.a];
    const mb = MATERIALS[r.b];
    const mo = MATERIALS[r.ok];
    const mf = MATERIALS[r.fail];
    if (!ma || !mb || !mo || !mf) {
      bad.push(`配方 ${r.a} + ${r.b} 的 id 不存在（合成时会抛异常、冻住主循环）`);
      continue;
    }
    if (ma.kind !== 'struct' || mb.kind !== 'struct' || mo.kind !== 'struct' || mf.kind !== 'struct') {
      bad.push(`配方 ${r.a} + ${r.b} 里混进了非结构件（功能材料/修复材料不能合成）`);
    }
    if (ma.tier !== mb.tier) {
      bad.push(`配方 ${r.a} + ${r.b} 的两件投入材料不同档（${ma.tier} / ${mb.tier}）`);
    }
    if (mo.tier !== ma.tier + 2) {
      bad.push(`配方 ${r.a} + ${r.b} 的成功产物 ${r.ok} 不是高两档（产品 tier ${mo.tier}，期望 ${ma.tier + 2}）`);
    }
    if (mf.tier !== ma.tier + 1) {
      bad.push(`配方 ${r.a} + ${r.b} 的失败产物 ${r.fail} 不是"次X级"（tier ${mf.tier}，期望 ${ma.tier + 1}）`);
    }
    if (SYNTH.successRate[ma.tier] === undefined || SYNTH.scrapShare[ma.tier] === undefined) {
      bad.push(`档位 ${ma.tier}（配方 ${r.a} + ${r.b}）没在 SYNTH.successRate / scrapShare 里声明`
        + ` → 查不到会让成功率静默变成 0`);
    }
    const key = `${r.a}|${r.b}`;
    if (seen.has(key)) bad.push(`配方 ${r.a} + ${r.b} 重复定义`);
    seen.add(key);
  }
  if (!SYNTH_RECIPES.length) bad.push('配方表是空的（合成系统等于不存在）');
  if (bad.length) {
    throw new Error('合成配方表自检没过（会冻住主循环、或让成功率静默变成 0）：\n  ' + bad.join('\n  '));
  }
}
